// Original practice questions tagged by official section (I–IV).
// NASAA exam questions are copyrighted; these are original items
// written to drill the same concepts. Distribution mirrors exam weighting.

const BASE_QUESTIONS = [
  // ---------------- SECTION I — Economic Factors (8%) ----------------
  { id: 'q-I-1', sec: 'I', q: 'An investment\'s internal rate of return (IRR) is best described as the discount rate at which:', opts: ['Future value equals present value', 'Net present value equals zero', 'The Sharpe ratio is maximized', 'Beta equals 1.0'], correct: 1, exp: 'IRR is the discount rate that makes a project\'s NPV equal to zero — effectively its annualized return.' },
  { id: 'q-I-2', sec: 'I', q: 'Which statistic measures the TOTAL risk (volatility) of an investment\'s returns?', opts: ['Beta', 'Standard deviation', 'Alpha', 'Correlation'], correct: 1, exp: 'Standard deviation captures total volatility (systematic + unsystematic). Beta measures only systematic risk.' },
  { id: 'q-I-3', sec: 'I', q: 'The Sharpe ratio measures:', opts: ['Return per unit of systematic risk', 'Return per unit of total risk', 'A stock\'s sensitivity to the market', 'The correlation between two assets'], correct: 1, exp: 'Sharpe = (return − risk-free rate) ÷ standard deviation, i.e., return per unit of total risk. Treynor uses beta.' },
  { id: 'q-I-4', sec: 'I', q: 'A company\'s quick ratio differs from its current ratio because the quick ratio:', opts: ['Adds inventory to current assets', 'Excludes inventory from current assets', 'Uses total assets instead of current assets', 'Ignores current liabilities'], correct: 1, exp: 'The quick (acid-test) ratio removes inventory, a less liquid asset, for a stricter liquidity measure.' },
  { id: 'q-I-5', sec: 'I', q: 'A stock trades at $60 with EPS of $4. Its P/E ratio is:', opts: ['4', '15', '24', '0.067'], correct: 1, exp: 'P/E = price ÷ EPS = $60 ÷ $4 = 15. Investors pay $15 per dollar of earnings.' },
  { id: 'q-I-6', sec: 'I', q: 'Two assets with a correlation coefficient of −0.8 will, when combined in a portfolio:', opts: ['Increase total risk', 'Provide strong diversification benefits', 'Always move together', 'Have no effect on standard deviation'], correct: 1, exp: 'Negative correlation means the assets tend to move oppositely, reducing portfolio standard deviation — strong diversification.' },

  // ---------------- SECTION II — Investment Vehicles (17%) ----------------
  { id: 'q-II-1', sec: 'II', q: 'Commercial paper is best described as:', opts: ['Long-term secured corporate debt', 'Unsecured short-term corporate debt maturing in 270 days or less', 'A government-guaranteed money market fund', 'Equity issued by a startup'], correct: 1, exp: 'Commercial paper is unsecured short-term corporate debt (≤270 days), issued at a discount and exempt from registration.' },
  { id: 'q-II-2', sec: 'II', q: 'A bond trading at a premium will have which yield relationship?', opts: ['Nominal < Current Yield < YTM', 'YTM > Current Yield > Nominal', 'Nominal > Current Yield > YTM > YTC', 'All yields are equal'], correct: 2, exp: 'On a premium bond, yields rank Nominal > Current Yield > YTM > YTC. The relationship inverts for discount bonds.' },
  { id: 'q-II-3', sec: 'II', q: 'Which bond has the GREATEST sensitivity to interest-rate changes, all else equal?', opts: ['A short-term, high-coupon bond', 'A long-term zero-coupon bond', 'A money market instrument', 'A floating-rate note'], correct: 1, exp: 'Longer maturity and lower (zero) coupon both increase duration, making a long-term zero the most rate-sensitive.' },
  { id: 'q-II-4', sec: 'II', q: 'Cumulative preferred stock provides that:', opts: ['Dividends can be skipped permanently', 'Unpaid dividends accumulate and must be paid before common dividends', 'Holders always have voting rights', 'It converts automatically to common stock'], correct: 1, exp: 'Cumulative preferred accrues skipped dividends as arrears, which must be paid in full before any common dividend.' },
  { id: 'q-II-5', sec: 'II', q: 'An open-end mutual fund\'s shares are priced:', opts: ['Continuously throughout the trading day', 'Once per day at NAV after the market close (forward pricing)', 'At a premium or discount to NAV on an exchange', 'Only when the fund terminates'], correct: 1, exp: 'Open-end funds use forward pricing — orders receive the next NAV calculated once daily after the close.' },
  { id: 'q-II-6', sec: 'II', q: 'The key difference between an ETN and an ETF is that an ETN:', opts: ['Trades only once per day', 'Is an unsecured debt obligation carrying issuer credit risk', 'Cannot track an index', 'Is always actively managed'], correct: 1, exp: 'An ETN is unsecured bank debt — it carries the issuer\'s credit risk. An ETF actually holds the underlying assets.' },
  { id: 'q-II-7', sec: 'II', q: 'An investor who owns stock and buys a put option has created a:', opts: ['Covered call', 'Protective put', 'Naked put', 'Bull call spread'], correct: 1, exp: 'Owning the stock plus buying a put is a protective put — downside insurance that preserves upside.' },
  { id: 'q-II-8', sec: 'II', q: 'Which product is NOT considered a security?', opts: ['Variable annuity', 'Fixed annuity', 'Variable life insurance', 'Mutual fund'], correct: 1, exp: 'A fixed annuity is insurance-regulated (insurer bears the risk) and is not a security. Variable products are securities.' },
  { id: 'q-II-9', sec: 'II', q: 'A REIT must distribute at least what portion of its taxable income to maintain its tax status?', opts: ['50%', '75%', '90%', '100%'], correct: 2, exp: 'A REIT must distribute at least 90% of taxable income to investors, allowing pass-through tax treatment.' },
  { id: 'q-II-10', sec: 'II', q: 'A leveraged 3x ETF is generally MOST appropriate for:', opts: ['A long-term retirement holding', 'Short-term tactical trading', 'A conservative income investor', 'A capital-preservation objective'], correct: 1, exp: 'Daily rebalancing causes compounding decay over time, so leveraged/inverse funds suit short-term tactical use, not buy-and-hold.' },
  { id: 'q-II-11', sec: 'II', q: 'A SPAC is best described as:', opts: ['A municipal bond fund', 'A blank-check company that raises IPO funds to acquire an unidentified target', 'A type of REIT', 'A government money market fund'], correct: 1, exp: 'A SPAC (special-purpose acquisition company) is a blank-check shell that IPOs to later acquire a private company.' },
  { id: 'q-II-12', sec: 'II', q: 'A Class B mutual fund share is typically associated with:', opts: ['A front-end sales load', 'A contingent deferred sales charge that declines over time', 'No fees of any kind', 'Mandatory institutional minimums'], correct: 1, exp: 'Class B shares carry a back-end CDSC that declines the longer shares are held, often converting to Class A later.' },

  // ---------------- SECTION III — Client Recommendations (30%) ----------------
  { id: 'q-III-1', sec: 'III', q: 'In a limited partnership, the limited partners:', opts: ['Manage day-to-day operations', 'Have unlimited liability', 'Are passive with liability limited to their investment', 'Must be accredited investors'], correct: 2, exp: 'Limited partners are passive investors whose liability is capped at their contribution; the general partner manages and has unlimited liability.' },
  { id: 'q-III-2', sec: 'III', q: 'Which client is generally able to hold the LARGEST allocation to equities?', opts: ['A 68-year-old needing income next year', 'A 30-year-old saving for retirement in 35 years', 'A foundation needing to fund grants this year', 'A client with a 1-year time horizon'], correct: 1, exp: 'A long time horizon and growth objective let a young investor tolerate equity volatility for higher expected returns.' },
  { id: 'q-III-3', sec: 'III', q: 'CAPM expresses an asset\'s expected return as:', opts: ['Rf + β(Rm − Rf)', 'Return ÷ standard deviation', 'Dividends ÷ price', 'Net income ÷ equity'], correct: 0, exp: 'CAPM: Expected Return = Risk-free rate + Beta × (Market return − Risk-free rate), pricing systematic risk.' },
  { id: 'q-III-4', sec: 'III', q: 'Under the semi-strong form of the Efficient Market Hypothesis:', opts: ['Only past prices are reflected in price', 'All public information is already reflected, so fundamental analysis cannot consistently add value', 'Even insider information is priced in', 'Markets are always wrong'], correct: 1, exp: 'Semi-strong EMH says all public info is priced in, implying fundamental analysis cannot consistently beat the market.' },
  { id: 'q-III-5', sec: 'III', q: 'Dollar-cost averaging involves:', opts: ['Investing a fixed dollar amount at regular intervals', 'Buying a fixed number of shares each period', 'Timing the market\'s bottom', 'Selling losers to offset gains'], correct: 0, exp: 'DCA invests a constant dollar amount regularly, buying more shares when prices are low and fewer when high.' },
  { id: 'q-III-6', sec: 'III', q: 'Long-term capital gains apply to assets held for:', opts: ['Any length of time', 'More than one year', 'More than 30 days', 'More than five years'], correct: 1, exp: 'Assets held more than one year qualify for long-term capital-gains rates (0/15/20%). One year or less is short-term.' },
  { id: 'q-III-7', sec: 'III', q: 'The wash sale rule disallows a loss when a substantially identical security is purchased:', opts: ['Within 30 days before or after the sale', 'Only on the same day', 'Within 90 days after the sale', 'In a different account only'], correct: 0, exp: 'A loss is disallowed if a substantially identical security is bought within 30 days before or after the sale (a 61-day window).' },
  { id: 'q-III-8', sec: 'III', q: 'Which account has NO required minimum distributions for the original owner?', opts: ['Traditional IRA', 'Roth IRA', '401(k)', 'SEP-IRA'], correct: 1, exp: 'Roth IRAs have no RMDs during the original owner\'s lifetime; traditional accounts require RMDs beginning at age 73.' },
  { id: 'q-III-9', sec: 'III', q: 'Inherited securities generally receive what cost basis?', opts: ['The decedent\'s original cost (carryover)', 'Zero', 'Stepped-up to fair market value at date of death', 'The average of cost and value'], correct: 2, exp: 'Inherited assets receive a stepped-up basis to fair market value at death, eliminating prior unrealized gains.' },
  { id: 'q-III-10', sec: 'III', q: 'An HSA offers a "triple tax advantage." Which is NOT one of the three?', opts: ['Tax-deductible contributions', 'Tax-free growth', 'Tax-free qualified medical withdrawals', 'Employer matching is guaranteed'], correct: 3, exp: 'The triple advantage is deductible in, tax-free growth, tax-free qualified withdrawals. Employer matching is not a feature/guarantee.' },
  { id: 'q-III-11', sec: 'III', q: 'In JTWROS, when one owner dies, that owner\'s share:', opts: ['Passes to their estate', 'Passes automatically to the surviving owner(s)', 'Is frozen until probate', 'Reverts to the broker-dealer'], correct: 1, exp: 'JTWROS includes rights of survivorship — a deceased owner\'s share passes directly to survivors, bypassing probate.' },
  { id: 'q-III-12', sec: 'III', q: 'Which order executes immediately at the best available price?', opts: ['Limit order', 'Stop order', 'Market order', 'Fill-or-kill limit'], correct: 2, exp: 'A market order executes right away at the best available price; limit/stop orders impose price conditions.' },
  { id: 'q-III-13', sec: 'III', q: 'Time-weighted return is preferred over dollar-weighted return when:', opts: ['Measuring the impact of an investor\'s cash-flow timing', 'Evaluating a portfolio manager\'s skill independent of client deposits/withdrawals', 'Calculating current yield', 'Determining tax basis'], correct: 1, exp: 'Time-weighted return removes the effect of client cash flows, isolating the manager\'s performance — the standard for comparison.' },
  { id: 'q-III-14', sec: 'III', q: 'Under ERISA Section 404(c), if a plan offers a broad range of choices and information, then:', opts: ['The employer guarantees returns', 'Participants who direct their investments bear that selection responsibility', 'No fiduciary duties exist', 'The plan must use only annuities'], correct: 1, exp: '404(c) shifts investment-selection liability to participants when the plan provides sufficient choices and disclosures.' },
  { id: 'q-III-15', sec: 'III', q: 'A C-corporation\'s dividends create what tax issue for shareholders?', opts: ['Tax-free income', 'Double taxation (corporate then shareholder level)', 'Pass-through treatment', 'No taxation until sale'], correct: 1, exp: 'C-corp profits are taxed at the entity level and again as dividends to shareholders — double taxation. S-corps are pass-through.' },
  { id: 'q-III-16', sec: 'III', q: 'Tactical asset allocation differs from strategic allocation because it:', opts: ['Never changes the portfolio', 'Makes short-term shifts to exploit market opportunities', 'Sets the long-term target weights', 'Eliminates the need for rebalancing'], correct: 1, exp: 'Strategic allocation sets long-term targets; tactical allocation makes short-term tilts to capture opportunities.' },

  // ---------------- SECTION IV — Laws & Ethics (45%) ----------------
  { id: 'q-IV-1', sec: 'IV', q: 'The three-part test for "investment adviser" status requires all of the following EXCEPT:', opts: ['Receiving compensation', 'Being in the business of advising', 'Giving advice about securities', 'Managing at least $25 million'], correct: 3, exp: 'The three-part test is compensation + in the business + advice about securities. There is no AUM threshold in the definition itself.' },
  { id: 'q-IV-2', sec: 'IV', q: 'An adviser with $250 million in AUM registers with:', opts: ['The state(s) only', 'The SEC (federal covered)', 'FINRA', 'No registration required'], correct: 1, exp: 'At ≥ $110M AUM the adviser must register with the SEC as a federal covered adviser and notice-file with states.' },
  { id: 'q-IV-3', sec: 'IV', q: 'Investment adviser representatives (IARs) register with:', opts: ['The SEC only', 'The states where they have a place of business', 'FINRA only', 'No one'], correct: 1, exp: 'IARs register at the state level (even for federal covered advisers) wherever they maintain a place of business.' },
  { id: 'q-IV-4', sec: 'IV', q: 'NASAA\'s IAR continuing education requirement is:', opts: ['No CE is required', '12 credits annually: 6 Products & Practices + 6 Ethics', '40 hours every three years', 'Only firm-element training'], correct: 1, exp: 'The NASAA model rule requires 12 IAR CE credits per year — 6 Products & Practices and 6 Ethics & Professional Responsibility.' },
  { id: 'q-IV-5', sec: 'IV', q: 'Form ADV Part 2A is also known as the:', opts: ['Brochure supplement', 'Client brochure (plain English)', 'Trade confirmation', 'Consent order'], correct: 1, exp: 'Part 2A is the plain-English client brochure; Part 2B is the supplement covering specific advisory personnel.' },
  { id: 'q-IV-6', sec: 'IV', q: 'An agent\'s state registration:', opts: ['Is permanent regardless of employment', 'Is tied to a sponsoring firm and ends when employment ends', 'Is granted by FINRA only', 'Requires no firm affiliation'], correct: 1, exp: 'An agent\'s registration depends on a sponsoring BD/issuer; it terminates when that employment ends.' },
  { id: 'q-IV-7', sec: 'IV', q: 'Which is an EXEMPT security under the Uniform Securities Act?', opts: ['A speculative oil & gas program', 'Common stock of a private startup', 'U.S. Treasury and municipal securities', 'A non-traded REIT'], correct: 2, exp: 'Government and municipal securities are exempt securities. Private placements are exempt transactions, not exempt securities.' },
  { id: 'q-IV-8', sec: 'IV', q: 'Under Regulation D Rule 506(c), the issuer may:', opts: ['Sell to up to 35 non-accredited investors', 'Use general solicitation but sell only to verified accredited investors', 'Raise no more than $5 million', 'Avoid all antifraud rules'], correct: 1, exp: 'Rule 506(c) permits general solicitation but requires all purchasers to be accredited and their status reasonably verified.' },
  { id: 'q-IV-9', sec: 'IV', q: 'To qualify as an accredited investor by net worth, an individual must have net worth exceeding:', opts: ['$200,000 including home', '$500,000', '$1 million excluding primary residence', '$2.2 million'], correct: 2, exp: 'Accredited status by net worth requires more than $1M excluding the primary residence (or income > $200K/$300K for two years).' },
  { id: 'q-IV-10', sec: 'IV', q: 'A wronged investor\'s remedy of rescission entitles them to:', opts: ['Triple damages', 'Their purchase price plus interest, less income received', 'A criminal conviction of the seller', 'Only their original principal'], correct: 1, exp: 'Rescission returns the purchase price plus interest, minus any income already received from the investment.' },
  { id: 'q-IV-11', sec: 'IV', q: 'Under the Uniform Securities Act, criminal penalties for a willful violation can reach:', opts: ['1 year and $1,000', '3 years and $5,000', '5 years and $10,000', '10 years and $250,000'], correct: 1, exp: 'The USA provides up to 3 years imprisonment and a $5,000 fine per willful violation.' },
  { id: 'q-IV-12', sec: 'IV', q: 'The civil statute of limitations under the USA is the earlier of:', opts: ['1 year after discovery or 2 years after sale', '2 years after discovery or 3 years after the sale', '3 years after discovery or 5 years after sale', '6 years in all cases'], correct: 1, exp: 'A civil suit must be brought within the earlier of 2 years after discovery or 3 years after the sale.' },
  { id: 'q-IV-13', sec: 'IV', q: 'The fiduciary standard owed by investment advisers is:', opts: ['Lower than suitability', 'Equal to suitability', 'The highest standard — best interest, with duties of loyalty and care', 'Applicable only to discretionary accounts'], correct: 2, exp: 'Advisers owe a fiduciary duty — the highest standard — comprising loyalty (disclose conflicts) and care (suitable advice).' },
  { id: 'q-IV-14', sec: 'IV', q: 'An adviser is deemed to have custody when it:', opts: ['Gives advice for a fee', 'Holds or has access to client funds or securities', 'Charges an hourly rate', 'Has more than 5 clients'], correct: 1, exp: 'Custody means holding or having access to client funds/securities — triggering qualified custodian, surprise audit, and disclosure rules.' },
  { id: 'q-IV-15', sec: 'IV', q: 'An agent who transacts in securities not approved by their broker-dealer is engaged in:', opts: ['Churning', 'Front-running', 'Selling away', 'Arbitrage'], correct: 2, exp: 'Selling away is transacting in securities outside the BD\'s knowledge/approval — a prohibited practice.' },
  { id: 'q-IV-16', sec: 'IV', q: 'Performance-based fees may be charged only to:', opts: ['All clients', 'Qualified clients (net worth > $2.7M or ≥ $1.4M managed)', 'Clients over age 59½', 'Accredited investors only'], correct: 1, exp: 'Performance fees are limited to qualified clients — net worth over $2.7M or at least $1.4M under management with the adviser (SEC thresholds effective 2026, adjusted for inflation every 5 years).' },
  { id: 'q-IV-17', sec: 'IV', q: 'It is unlawful for a registered person to tell a client that registration means:', opts: ['They must follow the law', 'The Administrator has approved or endorsed the security or person', 'They passed an exam', 'They are affiliated with a firm'], correct: 1, exp: 'Implying regulatory approval or endorsement based on registration is an unlawful representation.' },
  { id: 'q-IV-18', sec: 'IV', q: 'Discretionary authority in an advisory account generally requires:', opts: ['No documentation', 'Prior written authorization from the client', 'Only verbal consent indefinitely', 'Approval by FINRA'], correct: 1, exp: 'Discretion requires prior written authorization; verbal discretion is allowed only for time/price of a specific order for a limited time.' },
  { id: 'q-IV-19', sec: 'IV', q: 'Soft-dollar arrangements are permissible when they fall within the safe harbor that requires the benefit to be:', opts: ['Cash paid to the adviser personally', 'Research or brokerage services that benefit clients', 'Vacations for the adviser', 'Office rent'], correct: 1, exp: 'The §28(e) safe harbor permits soft dollars used for research/brokerage services that benefit clients — not personal perks.' },
  { id: 'q-IV-20', sec: 'IV', q: 'A state Administrator may do all of the following EXCEPT:', opts: ['Issue subpoenas and investigate', 'Deny, suspend, or revoke registrations', 'Imprison a violator without a court', 'Issue cease-and-desist orders'], correct: 2, exp: 'The Administrator has broad civil/administrative powers but cannot impose imprisonment — criminal penalties require the courts.' },
  { id: 'q-IV-21', sec: 'IV', q: 'Filing a Suspicious Activity Report (SAR) is part of compliance with:', opts: ['ERISA', 'Anti-money-laundering rules (Bank Secrecy Act/PATRIOT Act)', 'The wash sale rule', 'Regulation D'], correct: 1, exp: 'SARs are required under AML rules (BSA/USA PATRIOT Act) to report potentially illicit activity.' },
];

// ============================================================
// EXTENDED BANK — additional original items to power full mocks
// ============================================================
const EXTRA_QUESTIONS = [
  // ---------------- SECTION I — Economic Factors ----------------
  { id: 'x-I-1', sec: 'I', q: 'Net present value (NPV) is positive when:', opts: ['The discount rate equals the IRR', 'The present value of inflows exceeds the initial investment', 'The investment has no risk', 'Beta is greater than 1'], correct: 1, exp: 'A positive NPV means discounted inflows exceed the cost — the project adds value and should be accepted.' },
  { id: 'x-I-2', sec: 'I', q: 'Using the Rule of 72, roughly how long does money take to double at 6%?', opts: ['6 years', '12 years', '18 years', '24 years'], correct: 1, exp: '72 ÷ 6 = 12 years to double.' },
  { id: 'x-I-3', sec: 'I', q: 'Beta measures:', opts: ['Total risk', 'Systematic (market) risk', 'Inflation risk', 'Default risk'], correct: 1, exp: 'Beta gauges sensitivity to overall market moves — systematic risk. The market itself has a beta of 1.0.' },
  { id: 'x-I-4', sec: 'I', q: 'A portfolio with positive alpha has:', opts: ['Underperformed its risk-adjusted expectation', 'Outperformed the return predicted by CAPM', 'A beta of exactly 1.0', 'No systematic risk'], correct: 1, exp: 'Positive alpha means the portfolio beat the return CAPM predicted for its beta — value added.' },
  { id: 'x-I-5', sec: 'I', q: 'Which set of returns has the larger standard deviation? Set A: 9%, 10%, 11%. Set B: 2%, 10%, 18%.', opts: ['Set A', 'Set B', 'They are equal', 'Cannot be determined'], correct: 1, exp: 'Set B\'s returns scatter much farther from the mean, so its standard deviation (volatility) is larger.' },
  { id: 'x-I-6', sec: 'I', q: 'A high debt-to-equity ratio indicates:', opts: ['Strong liquidity', 'Greater financial leverage and risk', 'High profitability', 'Low valuation'], correct: 1, exp: 'A high debt-to-equity ratio means the firm relies heavily on borrowed funds — more financial leverage and risk.' },
  { id: 'x-I-7', sec: 'I', q: 'The price-to-book ratio compares market price to:', opts: ['Earnings per share', 'Dividends per share', 'Net asset (accounting) value per share', 'Sales per share'], correct: 2, exp: 'P/B compares the market price to book value (assets minus liabilities) per share.' },
  { id: 'x-I-8', sec: 'I', q: 'When IRR and NPV disagree on mutually exclusive projects, analysts generally prefer:', opts: ['IRR, always', 'NPV, because it measures dollar value added', 'Payback period', 'The higher beta project'], correct: 1, exp: 'NPV is preferred when the two conflict because it directly measures the dollar value created.' },

  // ---------------- SECTION II — Investment Vehicles ----------------
  { id: 'x-II-1', sec: 'II', q: 'FDIC insurance covers a depositor at one bank, per ownership category, up to:', opts: ['$100,000', '$250,000', '$500,000', 'Unlimited'], correct: 1, exp: 'FDIC insures up to $250,000 per depositor, per insured bank, per ownership category.' },
  { id: 'x-II-2', sec: 'II', q: 'When market interest rates rise, the price of an existing fixed-rate bond will:', opts: ['Rise', 'Fall', 'Stay the same', 'Double'], correct: 1, exp: 'Bond prices move inversely to rates — when rates rise, existing bond prices fall.' },
  { id: 'x-II-3', sec: 'II', q: 'A bond rated BB by S&P is classified as:', opts: ['Investment grade', 'High-yield (non-investment grade)', 'Government guaranteed', 'Tax-exempt'], correct: 1, exp: 'BB is below the BBB investment-grade cutoff, so it is high-yield ("junk").' },
  { id: 'x-II-4', sec: 'II', q: 'A callable bond is most likely to be called when interest rates have:', opts: ['Risen sharply', 'Fallen', 'Stayed flat', 'Become negative only'], correct: 1, exp: 'Issuers call bonds when rates fall, so they can refinance at a lower coupon — to the investor\'s disadvantage.' },
  { id: 'x-II-5', sec: 'II', q: 'An American Depositary Receipt (ADR) primarily exposes a U.S. investor to:', opts: ['No additional risk', 'Currency and political risk of the foreign issuer', 'Guaranteed dividends', 'FDIC insurance'], correct: 1, exp: 'ADRs represent foreign shares and carry the currency and political risks of the underlying company.' },
  { id: 'x-II-6', sec: 'II', q: 'Closed-end fund shares trade:', opts: ['Only at NAV', 'On an exchange at a market price that can differ from NAV', 'Once daily at NAV plus a load', 'Only through the issuer'], correct: 1, exp: 'Closed-end funds trade on exchanges at market prices that may be at a premium or discount to NAV.' },
  { id: 'x-II-7', sec: 'II', q: 'A unit investment trust (UIT) is best characterized as:', opts: ['An actively managed fund', 'A fixed, unmanaged portfolio with a termination date', 'A bank deposit', 'A type of option'], correct: 1, exp: 'A UIT holds a fixed portfolio, is not actively managed, and has a defined termination date.' },
  { id: 'x-II-8', sec: 'II', q: 'A 12b-1 fee compensates a fund for:', opts: ['Portfolio management only', 'Distribution and marketing costs', 'Custody of securities', 'Audit fees'], correct: 1, exp: '12b-1 fees cover distribution/marketing and are part of the expense ratio.' },
  { id: 'x-II-9', sec: 'II', q: 'Which share class typically carries a front-end sales load?', opts: ['Class A', 'Class B', 'Class C', 'Institutional'], correct: 0, exp: 'Class A shares charge a front-end load at purchase, often with breakpoint discounts.' },
  { id: 'x-II-10', sec: 'II', q: 'A letter of intent allows a mutual fund investor to:', opts: ['Avoid all fees', 'Qualify for a breakpoint by committing to invest a stated amount within 13 months', 'Redeem without tax', 'Guarantee returns'], correct: 1, exp: 'A 13-month letter of intent lets an investor get breakpoint pricing now by pledging future purchases.' },
  { id: 'x-II-11', sec: 'II', q: 'The buyer of a call option is:', opts: ['Obligated to sell the underlying', 'Bullish and has the right to buy the underlying', 'Bearish and has the right to sell', 'Always hedged'], correct: 1, exp: 'A call buyer is bullish and holds the right (not obligation) to buy at the strike price.' },
  { id: 'x-II-12', sec: 'II', q: 'Selling a covered call generates income but:', opts: ['Removes all downside risk', 'Caps the upside on the underlying stock', 'Requires buying a put', 'Is only for bonds'], correct: 1, exp: 'A covered call earns premium income but caps gains if the stock rises above the strike.' },
  { id: 'x-II-13', sec: 'II', q: 'A futures contract differs from an option because the futures holder:', opts: ['Has only a right, not an obligation', 'Is obligated to complete the transaction', 'Pays no margin', 'Cannot lose money'], correct: 1, exp: 'Futures are binding obligations to buy/sell; options confer a right without obligation.' },
  { id: 'x-II-14', sec: 'II', q: 'A leveraged ETF that seeks 2x the daily index return is generally unsuitable for long-term holding because of:', opts: ['FDIC limits', 'Compounding/decay from daily rebalancing', 'A front-end load', 'Currency risk'], correct: 1, exp: 'Daily reset causes compounding decay over time, so leveraged ETFs suit short-term tactical use.' },
  { id: 'x-II-15', sec: 'II', q: 'A variable annuity is a security because:', opts: ['The insurer guarantees the return', 'The contract owner bears the investment risk via separate-account sub-accounts', 'It is FDIC insured', 'It pays a fixed rate'], correct: 1, exp: 'In a variable annuity the owner bears investment risk through sub-accounts, making it a security.' },
  { id: 'x-II-16', sec: 'II', q: 'Term life insurance is characterized by:', opts: ['Guaranteed cash value', 'A death benefit only, for a set period, at low cost', 'Investment sub-accounts', 'Flexible premiums and adjustable benefit'], correct: 1, exp: 'Term life is pure protection for a period with no cash value — the lowest-cost coverage.' },
  { id: 'x-II-17', sec: 'II', q: 'A digital asset is most likely to be deemed a security when it:', opts: ['Is used only as a medium of exchange', 'Meets the Howey test as an investment contract', 'Has a fixed supply', 'Is mined'], correct: 1, exp: 'If a token satisfies Howey (investment of money in a common enterprise expecting profit from others\' efforts), it is a security.' },
  { id: 'x-II-18', sec: 'II', q: 'A REIT that does not trade on an exchange is best described as:', opts: ['Highly liquid', 'Non-traded and relatively illiquid', 'A money market fund', 'A government bond'], correct: 1, exp: 'Non-traded REITs lack a public market, making them illiquid and harder to value and exit.' },

  // ---------------- SECTION III — Client Recommendations ----------------
  { id: 'x-III-1', sec: 'III', q: 'In a general partnership, the partners have:', opts: ['Limited liability', 'Unlimited joint liability', 'No tax reporting', 'Corporate double taxation'], correct: 1, exp: 'General partners share unlimited personal liability; income passes through to them.' },
  { id: 'x-III-2', sec: 'III', q: 'An S-corporation is taxed:', opts: ['At the entity level like a C-corp', 'As a pass-through to its shareholders', 'Only on dividends', 'Not at all'], correct: 1, exp: 'S-corp income passes through to shareholders, avoiding the double taxation of C-corps.' },
  { id: 'x-III-3', sec: 'III', q: 'Which investment objective carries the highest risk?', opts: ['Capital preservation', 'Income', 'Growth', 'Speculation'], correct: 3, exp: 'Speculation accepts the greatest risk in pursuit of the highest potential return.' },
  { id: 'x-III-4', sec: 'III', q: 'Risk capacity refers to a client\'s:', opts: ['Emotional willingness to take risk', 'Financial ability to absorb losses', 'Time of day they trade', 'Tax bracket only'], correct: 1, exp: 'Capacity is the financial ability to take risk; willingness is the attitudinal side. Both shape risk tolerance.' },
  { id: 'x-III-5', sec: 'III', q: 'Loss aversion, anchoring, and herding are examples of:', opts: ['Tax strategies', 'Behavioral finance biases', 'Order types', 'Bond features'], correct: 1, exp: 'These are behavioral finance biases that can distort investor decisions.' },
  { id: 'x-III-6', sec: 'III', q: 'The efficient frontier represents portfolios that:', opts: ['Have zero risk', 'Offer the maximum expected return for each level of risk', 'Use only bonds', 'Beat the market guaranteed'], correct: 1, exp: 'The efficient frontier is the set of portfolios maximizing expected return at each risk level.' },
  { id: 'x-III-7', sec: 'III', q: 'Under weak-form EMH, which analysis is said to add no consistent value?', opts: ['Fundamental analysis', 'Technical analysis', 'Tax analysis', 'Credit analysis'], correct: 1, exp: 'Weak-form EMH says past prices are already reflected, so technical (chart) analysis cannot consistently beat the market.' },
  { id: 'x-III-8', sec: 'III', q: 'Strategic asset allocation primarily involves:', opts: ['Short-term market timing', 'Setting and maintaining long-term target weights', 'Day trading', 'Buying only one stock'], correct: 1, exp: 'Strategic allocation sets long-term targets; tactical allocation makes shorter-term tilts.' },
  { id: 'x-III-9', sec: 'III', q: 'Rebalancing a portfolio tends to:', opts: ['Buy more of what rose and sell what fell', 'Sell what rose and buy what fell to restore targets', 'Eliminate all risk', 'Increase fees with no benefit'], correct: 1, exp: 'Rebalancing trims outperformers and adds to underperformers to restore target weights — disciplined "sell high, buy low."' },
  { id: 'x-III-10', sec: 'III', q: 'Qualified dividends are taxed at:', opts: ['Ordinary income rates', 'Long-term capital gains rates', '0% always', 'A flat 28%'], correct: 1, exp: 'Qualified dividends receive favorable long-term capital-gains rates if holding requirements are met.' },
  { id: 'x-III-11', sec: 'III', q: 'A taxpayer realizes a $5,000 short-term gain. It is taxed:', opts: ['At 0%', 'At long-term capital gains rates', 'As ordinary income', 'Only when withdrawn from an IRA'], correct: 2, exp: 'Short-term gains (assets held one year or less) are taxed as ordinary income.' },
  { id: 'x-III-12', sec: 'III', q: 'The alternative minimum tax (AMT) can be triggered by:', opts: ['Buying index funds', 'Exercising incentive stock options (the bargain element)', 'Holding municipal bonds from your home state', 'Earning wages only'], correct: 1, exp: 'The ISO bargain element is an AMT preference item that can trigger AMT.' },
  { id: 'x-III-13', sec: 'III', q: 'Portability in estate planning allows a surviving spouse to:', opts: ['Avoid all taxes forever', 'Use the deceased spouse\'s unused estate tax exemption', 'Skip probate automatically', 'Convert an IRA tax-free'], correct: 1, exp: 'Portability lets a surviving spouse use the decedent spouse\'s unused exclusion amount.' },
  { id: 'x-III-14', sec: 'III', q: 'A Traditional IRA owner must generally begin required minimum distributions at age:', opts: ['59½', '65', '70½', '73'], correct: 3, exp: 'Under current rules (SECURE 2.0), RMDs from Traditional IRAs begin at age 73.' },
  { id: 'x-III-15', sec: 'III', q: 'A distinguishing feature of a Roth IRA is:', opts: ['Tax-deductible contributions', 'Required minimum distributions at 73', 'Tax-free qualified withdrawals and no RMDs for the owner', 'Employer matching is mandatory'], correct: 2, exp: 'Roth IRAs offer tax-free qualified withdrawals and no RMDs during the original owner\'s life.' },
  { id: 'x-III-16', sec: 'III', q: 'A 403(b) plan is designed for employees of:', opts: ['Large public corporations', 'Public schools and 501(c)(3) nonprofits', 'The federal government only', 'Hedge funds'], correct: 1, exp: '403(b) plans serve public-school and tax-exempt nonprofit employees.' },
  { id: 'x-III-17', sec: 'III', q: 'A SEP-IRA allows employer contributions up to:', opts: ['$1,000', '10% of pay', '25% of compensation (subject to a dollar cap)', '100% of pay'], correct: 2, exp: 'SEP-IRA contributions can reach 25% of compensation, subject to the annual dollar limit.' },
  { id: 'x-III-18', sec: 'III', q: 'A direct (trustee-to-trustee) rollover avoids:', opts: ['Any change in custodian', 'The 20% mandatory withholding that applies to indirect rollovers', 'Diversification', 'RMDs forever'], correct: 1, exp: 'A direct rollover moves funds custodian-to-custodian and avoids the 20% withholding on indirect rollovers.' },
  { id: 'x-III-19', sec: 'III', q: 'ERISA applies to:', opts: ['Government employee plans', 'Church plans', 'Private-sector employer retirement plans', 'Individual brokerage accounts'], correct: 2, exp: 'ERISA governs private-sector employer plans; government and church plans are generally exempt.' },
  { id: 'x-III-20', sec: 'III', q: 'A Qualified Default Investment Alternative (QDIA) is commonly a:', opts: ['Single company stock', 'Target-date fund', 'Money market only', 'Cryptocurrency'], correct: 1, exp: 'Target-date funds are typical QDIAs, giving fiduciary protection for participants who do not choose investments.' },
  { id: 'x-III-21', sec: 'III', q: 'A 529 plan provides tax-free growth when used for:', opts: ['Any purchase', 'Qualified education expenses', 'Retirement income', 'Medical bills only'], correct: 1, exp: '529 plan earnings are tax-free when used for qualified education expenses.' },
  { id: 'x-III-22', sec: 'III', q: 'A Coverdell ESA limits annual contributions per beneficiary to:', opts: ['$2,000', '$6,500', '$22,500', 'Unlimited'], correct: 0, exp: 'Coverdell ESAs cap contributions at $2,000 per year per beneficiary, subject to income limits.' },
  { id: 'x-III-23', sec: 'III', q: 'In an UTMA account, control of the assets passes to the minor:', opts: ['Never', 'At the age of majority set by the state', 'Only at age 65', 'When the custodian dies'], correct: 1, exp: 'UTMA assets are irrevocable gifts that transfer to the minor at the state\'s age of majority.' },
  { id: 'x-III-24', sec: 'III', q: 'An HSA requires the owner to be enrolled in:', opts: ['Any health plan', 'A high-deductible health plan (HDHP)', 'Medicare', 'No health plan'], correct: 1, exp: 'HSAs require a qualifying high-deductible health plan and offer a triple tax advantage.' },
  { id: 'x-III-25', sec: 'III', q: 'Property titled JTWROS passes at death:', opts: ['Through probate to the estate', 'Automatically to the surviving joint owner(s)', 'To the state', 'Only via a will'], correct: 1, exp: 'JTWROS includes rights of survivorship — the share passes directly to surviving owners, bypassing probate.' },
  { id: 'x-III-26', sec: 'III', q: 'Tenancy by the entirety is a form of ownership reserved for:', opts: ['Business partners', 'Married couples', 'Any two people', 'Trustees'], correct: 1, exp: 'Tenancy by the entirety is available only to married couples and offers creditor protection.' },
  { id: 'x-III-27', sec: 'III', q: 'A limit order to buy at $50:', opts: ['Executes at any price immediately', 'Executes only at $50 or lower', 'Executes only at $50 or higher', 'Is a type of short sale'], correct: 1, exp: 'A buy limit executes at the limit price or better (lower), never above it.' },
  { id: 'x-III-28', sec: 'III', q: 'A principal (dealer) trade is one in which the firm:', opts: ['Acts as agent for a commission', 'Trades from its own inventory and charges a markup/markdown', 'Does not participate', 'Only buys municipal bonds'], correct: 1, exp: 'In a principal trade the firm buys/sells from its own account and earns a markup or markdown.' },
  { id: 'x-III-29', sec: 'III', q: 'Time-weighted return is most appropriate for:', opts: ['Measuring an investor\'s personal cash-flow timing', 'Comparing the skill of portfolio managers', 'Computing a bond\'s coupon', 'Estimating estate taxes'], correct: 1, exp: 'Time-weighted return removes the effect of client cash flows, isolating manager performance.' },

  // ---------------- SECTION IV — Laws & Ethics ----------------
  { id: 'x-IV-1', sec: 'IV', q: 'A person who gives advice about securities but receives NO compensation is:', opts: ['Always an investment adviser', 'Not meeting the compensation prong of the IA definition', 'A broker-dealer', 'An agent'], correct: 1, exp: 'Without compensation, the three-part IA test is not met — compensation is required.' },
  { id: 'x-IV-2', sec: 'IV', q: 'A lawyer who gives incidental securities advice as part of legal practice is:', opts: ['Always an IA', 'Generally excluded from the IA definition', 'Required to pass the Series 65', 'A federal covered adviser'], correct: 1, exp: 'Professionals (lawyers, accountants, teachers, engineers) are excluded when advice is incidental to their practice.' },
  { id: 'x-IV-3', sec: 'IV', q: 'A federal covered adviser must:', opts: ['Register fully in every state', 'Notice file (and pay fees) with states as required', 'Avoid all state contact', 'Register with FINRA'], correct: 1, exp: 'Federal covered advisers register with the SEC and notice file with states; they do not fully state-register.' },
  { id: 'x-IV-4', sec: 'IV', q: 'An adviser with $60 million in AUM (not advising investment companies) registers with:', opts: ['The SEC', 'The state(s) where it does business', 'FINRA', 'No one'], correct: 1, exp: 'Below $100M (mid-size), advisers generally register at the state level, not with the SEC.' },
  { id: 'x-IV-5', sec: 'IV', q: 'Form ADV Part 2B is the:', opts: ['Firm brochure', 'Brochure supplement covering specific advisory personnel', 'Trade confirmation', 'Customer agreement'], correct: 1, exp: 'Part 2B (brochure supplement) discloses information about the individuals who provide advice.' },
  { id: 'x-IV-6', sec: 'IV', q: 'An exempt reporting adviser (ERA) is typically an adviser to:', opts: ['Only retail clients', 'Private funds or venture capital funds', 'Banks', 'Government plans'], correct: 1, exp: 'ERAs advise private funds/venture capital and file limited reports while exempt from full registration.' },
  { id: 'x-IV-7', sec: 'IV', q: 'An IAR with no place of business in a state and only 4 retail clients there:', opts: ['Must register in that state', 'Qualifies for the de minimis exemption (≤5 clients)', 'Must register with the SEC', 'Cannot do business'], correct: 1, exp: 'With no office and 5 or fewer retail clients in the state, the de minimis exemption applies.' },
  { id: 'x-IV-8', sec: 'IV', q: 'When an agent moves from one broker-dealer to another, notice must be given by:', opts: ['Only the agent', 'Only the new firm', 'The agent, the old firm, and the new firm', 'No one'], correct: 2, exp: 'All three — the agent, old firm, and new firm — must notify the Administrator (via U4/U5).' },
  { id: 'x-IV-9', sec: 'IV', q: 'Which is an exempt transaction under the USA?', opts: ['A solicited retail sale of stock', 'An unsolicited customer order', 'An IPO to the general public', 'A cold-call sale'], correct: 1, exp: 'Unsolicited customer orders are classic exempt transactions, as are isolated non-issuer and institutional sales.' },
  { id: 'x-IV-10', sec: 'IV', q: 'Registration by coordination becomes effective:', opts: ['Only after 2 years', 'In tandem with the federal Securities Act registration', 'Never for new issues', 'Only by Administrator decree'], correct: 1, exp: 'Coordination ties state effectiveness to the federal registration becoming effective.' },
  { id: 'x-IV-11', sec: 'IV', q: 'Exchange-listed common stock is a federal covered security, meaning the state:', opts: ['Registers it fully', 'Cannot require notice filing or apply antifraud rules', 'May require notice filing and still applies antifraud authority', 'Bans it'], correct: 2, exp: 'States can require notice filings for covered securities and always retain antifraud jurisdiction.' },
  { id: 'x-IV-12', sec: 'IV', q: 'Under Reg D Rule 506(b), the issuer may sell to:', opts: ['Unlimited non-accredited investors', 'Up to 35 non-accredited (sophisticated) investors plus unlimited accredited, with no general solicitation', 'Only institutions', 'Anyone via advertising'], correct: 1, exp: '506(b) allows up to 35 sophisticated non-accredited investors plus unlimited accredited, but bars general solicitation.' },
  { id: 'x-IV-13', sec: 'IV', q: 'An accredited investor can qualify by having annual income exceeding:', opts: ['$50,000', '$100,000', '$200,000 individually ($300,000 joint) for two years', '$1,000,000'], correct: 2, exp: 'Income test: over $200K single / $300K joint in each of the last two years with the expectation it continues.' },
  { id: 'x-IV-14', sec: 'IV', q: 'The antifraud provisions of securities law apply to:', opts: ['Only registered securities', 'Only non-exempt transactions', 'All securities and transactions, even exempt ones', 'Only broker-dealers'], correct: 2, exp: 'Antifraud rules always apply — exemptions never exempt anyone from fraud liability.' },
  { id: 'x-IV-15', sec: 'IV', q: 'A state Administrator\'s jurisdiction extends to an offer that is:', opts: ['Only made in the state', 'Made in, from, or into the state', 'Only on a national exchange', 'Only by mail'], correct: 1, exp: 'The Administrator has authority over offers made in, from, or into the state.' },
  { id: 'x-IV-16', sec: 'IV', q: 'A cease-and-desist order may be issued by the Administrator:', opts: ['Only after a criminal trial', 'With or without a prior hearing, to stop a violation', 'Only by a federal court', 'Never'], correct: 1, exp: 'The Administrator can issue cease-and-desist orders, with or without a prior hearing, to halt violations.' },
  { id: 'x-IV-17', sec: 'IV', q: 'Civil liability under the USA generally allows the buyer to recover:', opts: ['Triple damages', 'The amount paid plus interest, less income received (rescission)', 'Only attorney fees', 'Nothing'], correct: 1, exp: 'The standard civil remedy is rescission: price paid plus interest, minus income received.' },
  { id: 'x-IV-18', sec: 'IV', q: 'It is a prohibited practice for an agent to:', opts: ['Recommend a suitable mutual fund', 'Guarantee a customer against loss', 'Disclose risks', 'Follow firm supervision'], correct: 1, exp: 'Guaranteeing against loss (or specific gains) is always prohibited.' },
  { id: 'x-IV-19', sec: 'IV', q: 'Churning refers to:', opts: ['Excessive trading to generate commissions', 'Investing for the long term', 'Buying index funds', 'Tax-loss harvesting'], correct: 0, exp: 'Churning is excessive trading in a client account primarily to generate commissions — a violation.' },
  { id: 'x-IV-20', sec: 'IV', q: 'Front-running is:', opts: ['Trading for your own account ahead of a known large client order', 'Selling away', 'A legitimate hedging method', 'A type of breakpoint'], correct: 0, exp: 'Front-running — trading personally ahead of a client\'s market-moving order — is prohibited.' },
  { id: 'x-IV-21', sec: 'IV', q: 'A registered person who recommends securities not offered through their firm is:', opts: ['Front-running', 'Selling away (prohibited without firm approval)', 'Rebalancing', 'Making a markup'], correct: 1, exp: 'Selling away — transacting outside the BD\'s approval/records — is prohibited.' },
  { id: 'x-IV-22', sec: 'IV', q: 'Performance-based fees are permitted for:', opts: ['Any retail client', 'Qualified clients only', 'Clients under 18', 'No one'], correct: 1, exp: 'Only qualified clients (net worth over $2.7M or $1.4M+ managed, SEC thresholds effective 2026) may be charged performance fees.' },
  { id: 'x-IV-23', sec: 'IV', q: 'A state-registered adviser that takes custody of client assets generally must:', opts: ['Do nothing extra', 'Use a qualified custodian, send notices, and meet a surprise audit / higher net worth or bond', 'Register with FINRA', 'Stop advising'], correct: 1, exp: 'Custody triggers qualified custodian, account-statement delivery, surprise exam, and (for state IAs) net worth/bond requirements.' },
  { id: 'x-IV-24', sec: 'IV', q: 'Verbal (oral) discretion over the time and price of an order is permitted:', opts: ['Indefinitely', 'For a limited period without full written authorization', 'Never', 'Only for bonds'], correct: 1, exp: 'Time/price discretion can be oral for a limited time; full discretion needs prior written authorization.' },
  { id: 'x-IV-25', sec: 'IV', q: 'Soft-dollar benefits are permissible when they consist of:', opts: ['Personal travel for the adviser', 'Research and brokerage services that benefit clients (Section 28(e) safe harbor)', 'Cash kickbacks', 'Office furniture'], correct: 1, exp: 'The 28(e) safe harbor covers research/brokerage that benefits clients — not personal perks.' },
  { id: 'x-IV-26', sec: 'IV', q: 'Filing a Suspicious Activity Report (SAR) is required under:', opts: ['ERISA', 'The Bank Secrecy Act / USA PATRIOT Act (AML)', 'Regulation D', 'The wash sale rule'], correct: 1, exp: 'SARs are part of AML compliance under the BSA and USA PATRIOT Act.' },
  { id: 'x-IV-27', sec: 'IV', q: 'Telling a client that state registration means the Administrator "approved" the adviser is:', opts: ['Acceptable', 'An unlawful representation', 'Required disclosure', 'Only allowed verbally'], correct: 1, exp: 'Implying regulatory approval/endorsement from registration is an unlawful representation.' },
  { id: 'x-IV-28', sec: 'IV', q: 'A NASAA model rule protects which group from financial exploitation?', opts: ['Accredited investors', 'Vulnerable adults', 'Market makers', 'Underwriters'], correct: 1, exp: 'NASAA\'s model act addresses financial exploitation of vulnerable adults (seniors and certain others).' },
  { id: 'x-IV-29', sec: 'IV', q: 'A broker-dealer with no place of business in a state that deals only with other broker-dealers and institutions is:', opts: ['Required to register in that state', 'Excluded from the state BD definition', 'A federal covered adviser', 'An agent'], correct: 1, exp: 'Such a firm is excluded from the state BD definition (no place of business + only institutional/BD counterparties).' },
  { id: 'x-IV-30', sec: 'IV', q: 'An investment advisory contract under the USA generally must:', opts: ['Permit assignment without consent', 'Be in writing and prohibit assignment without client consent', 'Allow performance fees for all clients', 'Be oral only'], correct: 1, exp: 'Advisory contracts must (for state IAs) be written, describe fees/services, and bar assignment without consent.' },
  { id: 'x-IV-31', sec: 'IV', q: 'Pay-to-play rules restrict advisers from:', opts: ['Charging any fees', 'Receiving government advisory business after certain political contributions', 'Advertising at all', 'Using soft dollars'], correct: 1, exp: 'Pay-to-play (Rule 206(4)-5) limits advisory business with government entities after certain political contributions.' },
  { id: 'x-IV-32', sec: 'IV', q: 'Personal-trading rules (SEC Rule 204A-1) require access persons to file:', opts: ['Nothing', 'Initial and quarterly securities holdings/transaction reports', 'A new Form ADV daily', 'Form U5'], correct: 1, exp: 'Access persons must submit initial and quarterly holdings/transactions reports under the code of ethics rule.' },
  { id: 'x-IV-33', sec: 'IV', q: 'A business continuity and succession plan is intended to:', opts: ['Increase commissions', 'Ensure client service continues after disruptions or an owner\'s departure', 'Avoid registration', 'Replace the Form ADV'], correct: 1, exp: 'BCP/succession planning protects clients by ensuring continuity after disasters or principal departures.' },
  { id: 'x-IV-34', sec: 'IV', q: 'Insider trading involves trading on:', opts: ['Public news', 'Material non-public information in breach of a duty', 'Technical chart patterns', 'A limit order'], correct: 1, exp: 'Insider trading is using material non-public information in breach of a fiduciary or similar duty.' },
];

// ============================================================
// EXPANDED BANK v2 — additional verified items (current 2026 figures)
// ============================================================
const EXTRA2_QUESTIONS = [
  // ---------------- SECTION I — Economic Factors ----------------
  { id: 'x2-I-1', sec: 'I', q: 'For the data set 4, 8, 8, 10, 20, what are the mode and the range?', opts: ['Mode 8, range 16', 'Mode 10, range 8', 'Mode 8, range 20', 'Mode 20, range 4'], correct: 0, exp: 'The mode is the most frequent value (8 appears twice); the range is highest minus lowest (20 − 4 = 16).' },
  { id: 'x2-I-2', sec: 'I', q: 'The Treynor ratio differs from the Sharpe ratio because Treynor measures excess return per unit of:', opts: ['Total risk (standard deviation)', 'Systematic risk (beta)', 'Inflation', 'Liquidity'], correct: 1, exp: 'Treynor divides excess return by beta (systematic risk); Sharpe divides by standard deviation (total risk).' },
  { id: 'x2-I-3', sec: 'I', q: 'A stock with a beta of 1.4 would be expected to move how much if the market rises 10%?', opts: ['Up about 7%', 'Up about 10%', 'Up about 14%', 'Down about 14%'], correct: 2, exp: 'Beta 1.4 means roughly 1.4× the market move: 1.4 × 10% ≈ 14%.' },
  { id: 'x2-I-4', sec: 'I', q: 'All else equal, the present value of a future sum decreases when:', opts: ['The discount rate decreases', 'The discount rate increases', 'The time period shortens', 'The future sum increases'], correct: 1, exp: 'A higher discount rate discounts future cash flows more heavily, lowering present value.' },
  { id: 'x2-I-5', sec: 'I', q: 'Current assets are $300,000 (including $120,000 inventory) and current liabilities are $150,000. The quick ratio is:', opts: ['2.0', '1.2', '0.8', '3.0'], correct: 1, exp: 'Quick ratio = (300,000 − 120,000) / 150,000 = 180,000 / 150,000 = 1.2.' },
  { id: 'x2-I-6', sec: 'I', q: 'A project should generally be accepted when its:', opts: ['IRR is below the required rate of return', 'NPV is negative', 'IRR exceeds the required rate of return', 'Payback equals zero'], correct: 2, exp: 'Accept when IRR exceeds the required return (equivalently, when NPV is positive).' },
  { id: 'x2-I-7', sec: 'I', q: 'Which pair of assets provides the GREATEST diversification benefit?', opts: ['Correlation of +1.0', 'Correlation of +0.5', 'Correlation of 0', 'Correlation of −0.9'], correct: 3, exp: 'The closer correlation is to −1.0, the more risk-reduction from combining the assets.' },
  { id: 'x2-I-8', sec: 'I', q: 'A high price-to-earnings (P/E) ratio most often signals that investors expect:', opts: ['Declining earnings', 'Strong future earnings growth (or possible overvaluation)', 'Bankruptcy', 'A bond default'], correct: 1, exp: 'A high P/E typically reflects expectations of strong growth — though it can also indicate overvaluation.' },
  { id: 'x2-I-9', sec: 'I', q: 'Working capital is calculated as:', opts: ['Current assets ÷ current liabilities', 'Current assets − current liabilities', 'Total assets − total liabilities', 'Net income ÷ equity'], correct: 1, exp: 'Working capital is a dollar amount: current assets minus current liabilities.' },
  { id: 'x2-I-10', sec: 'I', q: 'Standard deviation is most useful as a measure of:', opts: ['A bond\'s coupon', 'The dispersion/volatility of an investment\'s returns', 'A firm\'s tax rate', 'Dividend yield'], correct: 1, exp: 'Standard deviation quantifies how widely returns vary around the mean — a volatility (total risk) measure.' },

  // ---------------- SECTION II — Investment Vehicles ----------------
  { id: 'x2-II-1', sec: 'II', q: 'Treasury bills are issued:', opts: ['At a premium with semiannual coupons', 'At a discount with no periodic interest', 'At par with monthly interest', 'Only to banks'], correct: 1, exp: 'T-bills are zero-coupon instruments sold at a discount; the investor\'s return is par minus purchase price.' },
  { id: 'x2-II-2', sec: 'II', q: 'A money market mutual fund generally seeks to maintain a stable net asset value of:', opts: ['$10', '$1', '$100', 'Whatever the market sets'], correct: 1, exp: 'Money market funds aim to hold a stable $1.00 NAV (not guaranteed or insured).' },
  { id: 'x2-II-3', sec: 'II', q: 'A bond with a 5% coupon trading at $1,250 has a current yield of:', opts: ['5.0%', '4.0%', '6.25%', '2.5%'], correct: 1, exp: 'Current yield = annual interest ($50) ÷ market price ($1,250) = 4.0%. Because it is a premium bond, current yield is below the coupon.' },
  { id: 'x2-II-4', sec: 'II', q: 'Interest from a municipal bond is generally:', opts: ['Fully taxable federally', 'Exempt from federal income tax', 'Subject to a 28% flat rate', 'Taxed only as a capital gain'], correct: 1, exp: 'Municipal bond interest is exempt from federal income tax (and often from state tax for in-state residents).' },
  { id: 'x2-II-5', sec: 'II', q: 'A general obligation (GO) municipal bond is backed by:', opts: ['Revenue from a specific project', 'The full faith, credit, and taxing power of the issuer', 'The federal government', 'Corporate earnings'], correct: 1, exp: 'GO bonds are backed by the issuer\'s taxing power; revenue bonds are backed by a specific project\'s income.' },
  { id: 'x2-II-6', sec: 'II', q: 'A preemptive right allows an existing shareholder to:', opts: ['Vote twice', 'Maintain proportional ownership by buying new shares before the public', 'Convert stock to bonds', 'Receive guaranteed dividends'], correct: 1, exp: 'Preemptive (antidilution) rights let shareholders buy newly issued shares first to keep their ownership percentage.' },
  { id: 'x2-II-7', sec: 'II', q: 'A warrant differs from a right primarily because a warrant:', opts: ['Is short-term', 'Has a long-term (often years) life and a strike above current price at issue', 'Must be exercised immediately', 'Pays interest'], correct: 1, exp: 'Warrants are long-term equity purchase instruments, usually issued with a strike above market; rights are short-term.' },
  { id: 'x2-II-8', sec: 'II', q: 'The maximum gain on a covered call position is achieved when the stock:', opts: ['Falls to zero', 'Rises to or above the strike at expiration', 'Stays exactly flat', 'Pays no dividend'], correct: 1, exp: 'Max gain on a covered call = premium + (strike − cost), realized when the stock is at or above the strike and the call is exercised.' },
  { id: 'x2-II-9', sec: 'II', q: 'Rights of accumulation allow a mutual fund investor to:', opts: ['Avoid taxes on gains', 'Use the current value of existing holdings to reach a breakpoint on new purchases', 'Redeem without notice', 'Convert to an ETF'], correct: 1, exp: 'Rights of accumulation count existing account value toward breakpoint discounts on additional purchases.' },
  { id: 'x2-II-10', sec: 'II', q: 'An ETF typically trades at a price very close to its NAV because of:', opts: ['Government price controls', 'The creation/redemption (arbitrage) mechanism with authorized participants', 'A 12b-1 fee', 'FDIC insurance'], correct: 1, exp: 'Authorized participants create/redeem shares in kind, arbitraging away gaps between price and NAV.' },
  { id: 'x2-II-11', sec: 'II', q: 'An equity-indexed annuity credits interest based on an index, but its gains are limited by features such as:', opts: ['A guaranteed 10% return', 'Participation rates and caps', 'FDIC insurance', 'Daily NAV pricing'], correct: 1, exp: 'Indexed annuities use participation rates, caps, and sometimes spreads to limit the index-linked credit; a floor limits losses.' },
  { id: 'x2-II-12', sec: 'II', q: 'Variable life insurance is considered a security because:', opts: ['The death benefit is fixed', 'Cash value is invested in separate-account sub-accounts, placing investment risk on the owner', 'Premiums are tax-deductible', 'It is FDIC insured'], correct: 1, exp: 'Variable life invests cash value in sub-accounts; the owner bears investment risk, so it is a security.' },
  { id: 'x2-II-13', sec: 'II', q: 'Compared with an ETF, an exchange-traded note (ETN) adds which risk?', opts: ['Lower liquidity always', 'Issuer (credit) risk, since it is unsecured bank debt', 'Mandatory leverage', 'Currency risk only'], correct: 1, exp: 'An ETN is an unsecured debt obligation; if the issuing bank defaults, investors can lose money regardless of index performance.' },
  { id: 'x2-II-14', sec: 'II', q: 'A negotiable jumbo CD is distinguished by:', opts: ['A $250 minimum', 'A large denomination ($100,000+) that can be traded in a secondary market', 'No maturity date', 'Being uninsured equity'], correct: 1, exp: 'Negotiable (jumbo) CDs are large-denomination and tradable before maturity, unlike ordinary CDs.' },
  { id: 'x2-II-15', sec: 'II', q: 'Commercial paper qualifies for an exemption from registration when its maturity is:', opts: ['Up to 5 years', '270 days or less', 'Exactly 1 year', 'Over 10 years'], correct: 1, exp: 'Prime commercial paper maturing in 270 days or less is an exempt security.' },
  { id: 'x2-II-16', sec: 'II', q: 'Which security typically offers the highest priority claim in a corporate liquidation?', opts: ['Common stock', 'Preferred stock', 'Secured bondholders', 'Warrants'], correct: 2, exp: 'Secured creditors/bondholders are paid first; preferred precedes common, and common is paid last.' },
  { id: 'x2-II-17', sec: 'II', q: 'A structured product that is "principal-protected" still exposes the investor to:', opts: ['No risk at all', 'The credit risk of the issuing institution', 'Guaranteed losses', 'FDIC limits'], correct: 1, exp: 'Principal protection depends on the issuer\'s ability to pay — the buyer takes on issuer credit risk.' },
  { id: 'x2-II-18', sec: 'II', q: 'Hedge funds are generally limited to:', opts: ['Any retail investor', 'Accredited investors and qualified purchasers', 'Minors only', 'Government plans only'], correct: 1, exp: 'Private funds like hedge funds rely on exemptions and are limited to accredited investors / qualified purchasers.' },

  // ---------------- SECTION III — Client Recommendations ----------------
  { id: 'x2-III-1', sec: 'III', q: 'Under the SECURE Act, most non-spouse beneficiaries who inherit an IRA must fully distribute it within:', opts: ['1 year', '5 years', '10 years', 'Their lifetime'], correct: 2, exp: 'The SECURE Act\'s 10-year rule requires most non-spouse beneficiaries to empty an inherited IRA within 10 years.' },
  { id: 'x2-III-2', sec: 'III', q: 'A revocable living trust:', opts: ['Cannot be changed once created', 'Can be amended or revoked by the grantor during life and avoids probate', 'Is always irrevocable at death... no, it remains revocable', 'Eliminates all estate tax'], correct: 1, exp: 'A revocable trust can be changed by the grantor and passes assets outside probate, though it offers limited tax/creditor protection.' },
  { id: 'x2-III-3', sec: 'III', q: 'For 2026, the annual gift tax exclusion per recipient is:', opts: ['$15,000', '$17,000', '$19,000', '$1 million'], correct: 2, exp: 'The 2026 annual gift tax exclusion is $19,000 per recipient; gifts above it draw down the lifetime exclusion.' },
  { id: 'x2-III-4', sec: 'III', q: 'For 2026, the basic estate/gift lifetime exclusion is approximately:', opts: ['$5 million', '$11.7 million', '$13.99 million', '$15 million'], correct: 3, exp: 'Under the 2025 law (One Big Beautiful Bill), the 2026 basic exclusion amount is $15 million per person.' },
  { id: 'x2-III-5', sec: 'III', q: 'Capital losses can offset capital gains, and net losses can offset ordinary income up to how much per year?', opts: ['$1,000', '$3,000', '$10,000', 'Unlimited'], correct: 1, exp: 'Up to $3,000 of net capital losses can offset ordinary income annually; the remainder carries forward.' },
  { id: 'x2-III-6', sec: 'III', q: 'A married couple wants to minimize current taxes on investment income. Which is generally most tax-efficient?', opts: ['Frequent short-term trading', 'Holding investments over one year for long-term capital gains treatment', 'Buying only high-dividend C-corp stocks', 'Day trading in a taxable account'], correct: 1, exp: 'Holding more than a year qualifies for lower long-term capital-gains rates, improving tax efficiency.' },
  { id: 'x2-III-7', sec: 'III', q: 'Strong-form efficient market hypothesis asserts that prices reflect:', opts: ['Only past prices', 'Only public information', 'All information, including non-public (insider) information', 'No information'], correct: 2, exp: 'Strong-form EMH claims even private/insider information is already reflected in prices.' },
  { id: 'x2-III-8', sec: 'III', q: 'Sector rotation is a strategy that:', opts: ['Holds one stock forever', 'Shifts investments among industries based on the economic cycle', 'Avoids all equities', 'Uses only index funds'], correct: 1, exp: 'Sector rotation moves money into sectors expected to outperform at each stage of the business cycle.' },
  { id: 'x2-III-9', sec: 'III', q: 'A general partnership\'s income is:', opts: ['Taxed at the entity level', 'Passed through to the partners and taxed once on their returns', 'Tax-exempt', 'Double-taxed like a C-corp'], correct: 1, exp: 'Partnerships are pass-through entities; income is reported and taxed on the partners\' individual returns.' },
  { id: 'x2-III-10', sec: 'III', q: 'A client nearing retirement who needs income within a year should emphasize:', opts: ['Aggressive growth stocks', 'Speculative options', 'Capital preservation and income vehicles', 'A leveraged ETF'], correct: 2, exp: 'A short horizon and income need call for conservative, liquid, income-oriented investments.' },
  { id: 'x2-III-11', sec: 'III', q: 'In a tenants-in-common account, when one owner dies, that owner\'s share:', opts: ['Passes to the surviving owner automatically', 'Passes to the decedent\'s estate', 'Is forfeited to the broker', 'Must be sold immediately'], correct: 1, exp: 'TIC has no survivorship — a deceased owner\'s share passes to their estate, not the co-owner.' },
  { id: 'x2-III-12', sec: 'III', q: 'A 529 plan compared with a Coverdell ESA generally offers:', opts: ['A lower contribution limit', 'Much higher contribution limits with no income restriction on the donor', 'No tax advantages', 'Mandatory K-12 use'], correct: 1, exp: '529 plans allow high contributions with no donor income limits; Coverdell ESAs cap contributions at $2,000 and have income limits.' },
  { id: 'x2-III-13', sec: 'III', q: 'A qualified domestic relations order (QDRO) is used to:', opts: ['Open a 529 plan', 'Divide retirement plan assets in a divorce', 'Avoid RMDs', 'Convert a Roth IRA'], correct: 1, exp: 'A QDRO allows retirement plan assets to be split between spouses pursuant to a divorce decree.' },
  { id: 'x2-III-14', sec: 'III', q: 'Dollar-cost averaging tends to result in:', opts: ['Buying more shares when prices are high', 'A lower average cost per share than the average price over the period', 'Guaranteed profits', 'No share purchases in down markets'], correct: 1, exp: 'Fixed-dollar investing buys more shares when prices are low, lowering the average cost per share.' },
  { id: 'x2-III-15', sec: 'III', q: 'A donor-advised fund allows a donor to:', opts: ['Take a deduction now and recommend grants to charities over time', 'Avoid all taxes permanently', 'Reclaim donated funds', 'Guarantee investment returns'], correct: 0, exp: 'Donor-advised funds give an immediate charitable deduction while letting the donor advise on grants later.' },
  { id: 'x2-III-16', sec: 'III', q: 'Time-weighted return is generally used to evaluate:', opts: ['An individual investor\'s personal results including deposits', 'A portfolio manager\'s performance independent of client cash flows', 'A bond\'s accrued interest', 'A stock\'s beta'], correct: 1, exp: 'Time-weighted return strips out the effect of client contributions/withdrawals, isolating manager skill.' },
  { id: 'x2-III-17', sec: 'III', q: 'Margin accounts differ from cash accounts in that they:', opts: ['Require full payment for all purchases', 'Allow borrowing against securities, adding leverage and interest cost', 'Cannot hold equities', 'Are tax-exempt'], correct: 1, exp: 'A margin account lets the client borrow against securities, magnifying gains and losses and incurring interest.' },
  { id: 'x2-III-18', sec: 'III', q: 'Under ERISA, a prohibited transaction would include:', opts: ['Offering a diversified menu of funds', 'A fiduciary self-dealing with plan assets for personal benefit', 'Providing participant disclosures', 'Using a target-date QDIA'], correct: 1, exp: 'Self-dealing and conflicts between the plan and a party-in-interest are prohibited transactions under ERISA.' },
  { id: 'x2-III-19', sec: 'III', q: 'The "kiddie tax" can cause a child\'s unearned investment income above a threshold to be taxed:', opts: ['At 0% always', 'At the parents\' marginal rate', 'Never', 'As a gift'], correct: 1, exp: 'The kiddie tax taxes a child\'s unearned income above the annual threshold at the parents\' (higher) rate.' },
  { id: 'x2-III-20', sec: 'III', q: 'A 2026 investor under age 50 can contribute how much to a Traditional or Roth IRA?', opts: ['$6,000', '$7,000', '$7,500', '$23,000'], correct: 2, exp: 'The 2026 IRA contribution limit is $7,500 (those 50+ may add a $1,100 catch-up).' },
  { id: 'x2-III-21', sec: 'III', q: 'Real (inflation-adjusted) return is calculated by:', opts: ['Adding inflation to the nominal return', 'Subtracting inflation from the nominal return', 'Multiplying by beta', 'Ignoring inflation'], correct: 1, exp: 'Real return ≈ nominal return − inflation rate, reflecting actual purchasing-power growth.' },
  { id: 'x2-III-22', sec: 'III', q: 'A client values environmental and social factors. The adviser should:', opts: ['Ignore them — only returns matter', 'Incorporate ESG criteria consistent with the client\'s stated values and objectives', 'Refuse the account', 'Guarantee ESG outperformance'], correct: 1, exp: 'Non-financial factors such as ESG values are legitimate suitability inputs and should shape recommendations.' },

  // ---------------- SECTION IV — Laws & Ethics ----------------
  { id: 'x2-IV-1', sec: 'IV', q: 'A publisher of a bona fide general-circulation financial newspaper giving impersonal advice is:', opts: ['Always an investment adviser', 'Excluded from the IA definition', 'A federal covered adviser', 'A broker-dealer'], correct: 1, exp: 'Bona fide publishers of general, regular, impersonal publications are excluded from the IA definition.' },
  { id: 'x2-IV-2', sec: 'IV', q: 'Under the Uniform Securities Act, a "sale" includes:', opts: ['A gift of assessable stock', 'Only cash transactions', 'Investment advice', 'Opening a bank account'], correct: 0, exp: 'The USA defines a sale broadly; a gift of assessable stock is deemed a sale, and an offer includes solicitations.' },
  { id: 'x2-IV-3', sec: 'IV', q: 'Registration of a security by coordination becomes effective:', opts: ['Only after 1 year', 'Simultaneously with the federal registration becoming effective', 'Never for IPOs', 'Only by court order'], correct: 1, exp: 'Coordination ties state effectiveness to the SEC registration becoming effective (assuming state conditions are met).' },
  { id: 'x2-IV-4', sec: 'IV', q: 'A state-registered adviser must generally maintain its books and records for at least:', opts: ['1 year', '3 years', '5 years', '10 years'], correct: 2, exp: 'NASAA requires IA records to be kept 5 years, with the first 2 years in the principal office and readily accessible.' },
  { id: 'x2-IV-5', sec: 'IV', q: 'The consent to service of process filed with registration:', opts: ['Waives all client rights', 'Appoints the Administrator as agent to receive legal papers in actions against the registrant', 'Guarantees registration approval', 'Is renewed daily'], correct: 1, exp: 'The consent appoints the Administrator to accept service of process, and it remains in effect permanently.' },
  { id: 'x2-IV-6', sec: 'IV', q: 'Under the USA, the criminal statute of limitations for securities fraud is:', opts: ['1 year', '2 years', '3 years', '5 years'], correct: 3, exp: 'The USA criminal statute of limitations is 5 years; criminal penalties are up to 3 years imprisonment and a $5,000 fine.' },
  { id: 'x2-IV-7', sec: 'IV', q: 'A NASAA-registered adviser that maintains custody of client funds must typically keep minimum net worth of at least:', opts: ['$10,000', '$35,000', '$100,000', '$1 million'], correct: 1, exp: 'Under NASAA model rules, an adviser with custody must maintain $35,000 minimum net worth (or post a bond); discretion without custody requires $10,000.' },
  { id: 'x2-IV-8', sec: 'IV', q: 'An adviser that exercises discretion but does NOT have custody must maintain minimum net worth of at least:', opts: ['$10,000', '$35,000', '$50,000', '$0'], correct: 0, exp: 'Discretion without custody requires $10,000 minimum net worth under NASAA model rules.' },
  { id: 'x2-IV-9', sec: 'IV', q: 'Regulation D Rule 506(b) permits sales to:', opts: ['Unlimited non-accredited investors via advertising', 'Up to 35 non-accredited sophisticated investors plus unlimited accredited, with no general solicitation', 'Only banks', 'Anyone, with no conditions'], correct: 1, exp: '506(b) allows up to 35 sophisticated non-accredited investors and unlimited accredited investors, but prohibits general solicitation.' },
  { id: 'x2-IV-10', sec: 'IV', q: 'Rule 147 provides an exemption for:', opts: ['International offerings', 'Intrastate offerings sold only to residents of one state by an in-state issuer', 'Government bonds', 'Mutual funds'], correct: 1, exp: 'Rule 147 covers intrastate offerings where the issuer and all purchasers are in the same state, with resale limits.' },
  { id: 'x2-IV-11', sec: 'IV', q: 'Which individual is INCLUDED as an accredited investor under current SEC rules?', opts: ['Anyone with a bank account', 'A person holding a Series 7, 65, or 82 license in good standing', 'A minor', 'Any U.S. citizen'], correct: 1, exp: 'Since 2020, holders of Series 7, 65, or 82 licenses qualify as accredited investors regardless of income/net worth.' },
  { id: 'x2-IV-12', sec: 'IV', q: 'A broker-dealer acting as a principal in a trade must disclose on the confirmation:', opts: ['Nothing', 'Its capacity and any markup/markdown as required', 'The client\'s tax bracket', 'The Administrator\'s opinion'], correct: 1, exp: 'Confirmations (Rule 10b-10) must disclose the firm\'s capacity (agent vs. principal) and compensation details.' },
  { id: 'x2-IV-13', sec: 'IV', q: 'Market manipulation includes which prohibited practice?', opts: ['Best execution', 'Wash trades and matched orders that create false activity', 'Disclosing conflicts', 'Charging a commission'], correct: 1, exp: 'Creating misleading appearances of trading (wash sales, matched orders) is illegal market manipulation.' },
  { id: 'x2-IV-14', sec: 'IV', q: 'An agent may borrow money from a client only if:', opts: ['Never under any circumstances', 'The client is a bank or lending institution in the business of lending (and firm policy permits)', 'The client verbally agrees', 'The amount is small'], correct: 1, exp: 'Borrowing from clients is prohibited unless the client is a lending institution/affiliate and the firm permits it under its rules.' },
  { id: 'x2-IV-15', sec: 'IV', q: 'Pay-to-play rules generally impose a "timeout" on receiving compensation for advising a government client for:', opts: ['30 days', '6 months', '2 years after a triggering political contribution', 'Forever'], correct: 2, exp: 'Rule 206(4)-5 imposes a two-year timeout on compensation for advising a government entity after certain political contributions.' },
  { id: 'x2-IV-16', sec: 'IV', q: 'A federal covered security includes:', opts: ['A private placement', 'A security listed on the NYSE or Nasdaq', 'A local intrastate offering', 'A promissory note'], correct: 1, exp: 'Exchange-listed securities (and investment company shares) are federal covered securities, preempting state registration.' },
  { id: 'x2-IV-17', sec: 'IV', q: 'The marketing rule (SEC Rule 206(4)-1) permits client testimonials only if:', opts: ['They are always banned', 'Required disclosures are made and the adviser oversees and has a written agreement as applicable', 'They guarantee returns', 'They are paid in cash secretly'], correct: 1, exp: 'The modernized marketing rule allows testimonials/endorsements with disclosures, oversight, and required conditions.' },
  { id: 'x2-IV-18', sec: 'IV', q: 'An agent who effects securities transactions not recorded on the books of their broker-dealer is committing:', opts: ['Best execution', 'Selling away', 'Coordination', 'A markup'], correct: 1, exp: 'Selling away — transacting in securities outside the firm\'s knowledge and records — is prohibited.' },
  { id: 'x2-IV-19', sec: 'IV', q: 'The Administrator may summarily (without prior hearing) postpone or suspend a registration but must:', opts: ['Never provide a hearing', 'Promptly notify the registrant and provide an opportunity for a hearing', 'Get FINRA approval', 'Refund all fees'], correct: 1, exp: 'A summary action requires prompt notice and an opportunity for a hearing afterward.' },
  { id: 'x2-IV-20', sec: 'IV', q: 'A securities transaction with an institution such as a bank or insurance company is classified as:', opts: ['A non-exempt retail sale', 'An exempt (institutional) transaction', 'Always prohibited', 'A federal covered security'], correct: 1, exp: 'Transactions with institutional investors (banks, insurance companies, investment companies, broker-dealers) are exempt transactions under the USA.' },
  { id: 'x2-IV-21', sec: 'IV', q: 'Insider trading liability can extend to a "tippee" who:', opts: ['Reads a public press release', 'Trades on material non-public information knowing it was disclosed in breach of duty', 'Uses technical analysis', 'Places a limit order'], correct: 1, exp: 'A tippee is liable when trading on MNPI received from an insider who breached a duty, and the tippee knew or should have known.' },
  { id: 'x2-IV-22', sec: 'IV', q: 'An investment advisory contract must generally describe all of the following EXCEPT:', opts: ['Services to be provided and the fee', 'That it may not be assigned without consent', 'A guarantee of investment performance', 'How fees are calculated'], correct: 2, exp: 'Contracts state services, fees, and the no-assignment clause — but performance guarantees are prohibited, not required.' },
  { id: 'x2-IV-23', sec: 'IV', q: 'When delivering the brochure (Form ADV Part 2) under the NASAA model rule, an adviser must provide it:', opts: ['Only upon client request after one year', 'At least 48 hours before entering the contract, OR at the time of entering if the client has a 5-day penalty-free right to terminate', 'Only after the first trade', 'Never'], correct: 1, exp: 'The brochure must be delivered at least 48 hours before contracting, or at contracting if the client gets a 5-business-day penalty-free withdrawal right.' },
  { id: 'x2-IV-24', sec: 'IV', q: 'An adviser with discretionary authority and a conflict from receiving soft dollars must:', opts: ['Hide the arrangement', 'Disclose the soft-dollar arrangement and ensure it falls within the Section 28(e) safe harbor', 'Pay clients cash', 'Stop trading'], correct: 1, exp: 'Soft dollars must be disclosed and limited to research/brokerage benefiting clients under the 28(e) safe harbor.' },
  { id: 'x2-IV-25', sec: 'IV', q: 'A NASAA model rule specifically addresses protecting which group from financial exploitation, allowing delayed disbursements:', opts: ['Accredited investors', 'Vulnerable adults (e.g., seniors)', 'Broker-dealers', 'Market makers'], correct: 1, exp: 'The NASAA Model Act to Protect Vulnerable Adults permits reporting and temporary holds on suspected exploitation of seniors/vulnerable adults.' },
];

// ============================================================
// EXPANDED BANK v3 — deepens the pool toward ~300 for distinct mocks
// ============================================================
const EXTRA3_QUESTIONS = [
  // ---------------- SECTION I — Economic Factors ----------------
  { id: 'x3-I-1', sec: 'I', q: 'Which compounding frequency produces the highest future value, all else equal?', opts: ['Annual', 'Quarterly', 'Monthly', 'Daily'], correct: 3, exp: 'The more frequently interest compounds, the higher the future value; daily compounding beats monthly, quarterly, and annual.' },
  { id: 'x3-I-2', sec: 'I', q: 'A portfolio returns 12%, the risk-free rate is 2%, and its standard deviation is 20%. Its Sharpe ratio is:', opts: ['0.50', '0.60', '1.00', '0.10'], correct: 0, exp: 'Sharpe = (12% − 2%) / 20% = 10/20 = 0.50.' },
  { id: 'x3-I-3', sec: 'I', q: 'A portfolio is 50% in a stock with beta 1.4 and 50% in a stock with beta 0.6. The portfolio beta is:', opts: ['0.6', '1.0', '1.4', '2.0'], correct: 1, exp: 'Portfolio beta is the weighted average: 0.5(1.4) + 0.5(0.6) = 1.0.' },
  { id: 'x3-I-4', sec: 'I', q: 'In a right-skewed (positively skewed) distribution of returns, which is generally true?', opts: ['Mean is less than median', 'Mean is greater than median', 'Mean equals mode', 'There is no mode'], correct: 1, exp: 'A long right tail pulls the mean above the median in a positively skewed distribution.' },
  { id: 'x3-I-5', sec: 'I', q: 'If an analyst increases the discount rate used in a discounted cash flow valuation, the resulting value will:', opts: ['Increase', 'Decrease', 'Stay the same', 'Become negative automatically'], correct: 1, exp: 'A higher discount rate reduces the present value of future cash flows, lowering the valuation.' },
  { id: 'x3-I-6', sec: 'I', q: 'Combining two assets with a correlation of exactly +1.0 provides:', opts: ['Maximum diversification', 'No diversification benefit', 'Negative risk', 'Guaranteed returns'], correct: 1, exp: 'Perfectly positively correlated assets move identically, so there is no reduction in portfolio risk.' },
  { id: 'x3-I-7', sec: 'I', q: 'A firm has $600,000 in total debt and $400,000 in shareholders\' equity. Its debt-to-equity ratio is:', opts: ['0.67', '1.0', '1.5', '2.4'], correct: 2, exp: 'Debt-to-equity = 600,000 / 400,000 = 1.5.' },
  { id: 'x3-I-8', sec: 'I', q: 'A current ratio of 0.8 most likely indicates:', opts: ['Strong liquidity', 'Current liabilities exceed current assets — a potential liquidity concern', 'High profitability', 'Low leverage'], correct: 1, exp: 'A current ratio below 1.0 means current liabilities exceed current assets, signaling possible short-term liquidity problems.' },

  // ---------------- SECTION II — Investment Vehicles ----------------
  { id: 'x3-II-1', sec: 'II', q: 'Treasury Inflation-Protected Securities (TIPS) protect investors by:', opts: ['Paying a fixed high coupon', 'Adjusting principal with changes in the CPI', 'Guaranteeing stock-market returns', 'Being FDIC insured'], correct: 1, exp: 'TIPS adjust their principal value with the Consumer Price Index, protecting purchasing power from inflation.' },
  { id: 'x3-II-2', sec: 'II', q: 'A U.S. Treasury security with an original maturity greater than 10 years is a:', opts: ['Treasury bill', 'Treasury note', 'Treasury bond', 'Treasury STRIP only'], correct: 2, exp: 'T-bills mature in ≤1 year, notes in 2–10 years, and bonds in more than 10 years (up to 30).' },
  { id: 'x3-II-3', sec: 'II', q: 'A holder of a zero-coupon corporate bond in a taxable account generally must:', opts: ['Pay no tax until maturity', 'Report imputed (accreted) interest as taxable income each year despite receiving no cash', 'Deduct the discount annually', 'Treat all gains as tax-free'], correct: 1, exp: 'Zero-coupon bonds create "phantom income" — the annual accretion is taxable even though no interest is paid until maturity.' },
  { id: 'x3-II-4', sec: 'II', q: 'A convertible bond with $1,000 par and a conversion price of $50 has a conversion ratio of:', opts: ['10 shares', '20 shares', '50 shares', '5 shares'], correct: 1, exp: 'Conversion ratio = par ÷ conversion price = 1,000 ÷ 50 = 20 shares.' },
  { id: 'x3-II-5', sec: 'II', q: 'A bond with a duration of 7 will change in price by approximately how much if interest rates rise 1%?', opts: ['Up 7%', 'Down 7%', 'Down 1%', 'No change'], correct: 1, exp: 'Price change ≈ −duration × rate change = −7 × 1% = about a 7% decline.' },
  { id: 'x3-II-6', sec: 'II', q: 'The highest credit rating assigned by Moody\'s and S&P, respectively, is:', opts: ['Baa / BBB', 'Aaa / AAA', 'Ba / BB', 'C / D'], correct: 1, exp: 'Aaa (Moody\'s) and AAA (S&P) denote the highest credit quality / lowest default risk.' },
  { id: 'x3-II-7', sec: 'II', q: 'A mortgage REIT differs from an equity REIT in that it primarily:', opts: ['Owns and operates physical properties', 'Invests in real estate debt and earns interest spread income', 'Holds only Treasury bonds', 'Is FDIC insured'], correct: 1, exp: 'Mortgage REITs invest in mortgages/real estate debt and profit from interest spreads; equity REITs own properties.' },
  { id: 'x3-II-8', sec: 'II', q: 'A Section 1035 exchange allows an investor to:', opts: ['Avoid all taxes on stock sales', 'Exchange one annuity or life policy for another without immediate taxation', 'Convert an IRA to a Roth tax-free', 'Defer capital gains on real estate'], correct: 1, exp: 'A 1035 exchange permits a tax-free swap between like insurance/annuity contracts.' },
  { id: 'x3-II-9', sec: 'II', q: 'Before recommending a variable annuity, a registered person must deliver:', opts: ['Nothing', 'A prospectus', 'An FDIC notice', 'A municipal official statement'], correct: 1, exp: 'Variable annuities are securities; a prospectus must be delivered, and the owner bears the investment risk.' },
  { id: 'x3-II-10', sec: 'II', q: 'The maximum gain to the buyer of a put option occurs when the underlying stock:', opts: ['Rises above the strike', 'Falls to zero (gain = strike − premium)', 'Stays flat', 'Pays a dividend'], correct: 1, exp: 'A put buyer profits as the stock falls; maximum gain is the strike price minus the premium (stock at $0).' },
  { id: 'x3-II-11', sec: 'II', q: 'A call option has a $50 strike while the stock trades at $55. The call\'s intrinsic value is:', opts: ['$0', '$5', '$50', '$55'], correct: 1, exp: 'Call intrinsic value = max(0, stock − strike) = 55 − 50 = $5 (it is in-the-money).' },
  { id: 'x3-II-12', sec: 'II', q: 'Class A mutual fund shares reduce the front-end sales charge at investment levels called:', opts: ['12b-1 fees', 'Breakpoints', 'Redemption fees', 'Loads'], correct: 1, exp: 'Breakpoints are dollar thresholds at which the Class A front-end sales charge is discounted.' },
  { id: 'x3-II-13', sec: 'II', q: 'A closed-end fund trading below its net asset value is said to trade at a:', opts: ['Premium', 'Discount', 'Par', 'Load'], correct: 1, exp: 'When market price is below NAV, the closed-end fund trades at a discount; above NAV is a premium.' },
  { id: 'x3-II-14', sec: 'II', q: 'A floating-rate (adjustable-rate) preferred stock primarily reduces which risk versus fixed-rate preferred?', opts: ['Credit risk', 'Interest-rate risk', 'Liquidity risk', 'Currency risk'], correct: 1, exp: 'Because its dividend resets with a benchmark, a floating-rate preferred has less interest-rate (price) risk than fixed-rate preferred.' },

  // ---------------- SECTION III — Client Recommendations ----------------
  { id: 'x3-III-1', sec: 'III', q: 'A municipal bond yields 4%. For an investor in the 32% federal bracket, the tax-equivalent yield is approximately:', opts: ['4.0%', '5.0%', '5.88%', '2.72%'], correct: 2, exp: 'Tax-equivalent yield = muni yield ÷ (1 − tax rate) = 4% ÷ 0.68 ≈ 5.88%.' },
  { id: 'x3-III-2', sec: 'III', q: 'The 3.8% Net Investment Income Tax applies to:', opts: ['All taxpayers equally', 'High-income taxpayers above MAGI thresholds, on investment income', 'Only municipal bond interest', 'IRA contributions'], correct: 1, exp: 'The NIIT adds 3.8% on net investment income for taxpayers above the MAGI thresholds ($200k single / $250k MFJ).' },
  { id: 'x3-III-3', sec: 'III', q: 'To be a "qualified dividend" taxed at favorable rates, the shares must generally be held for more than:', opts: ['30 days', '60 days around the ex-dividend date', '1 year', '5 years'], correct: 1, exp: 'Qualified dividends require holding the stock more than 60 days during the 121-day window around the ex-dividend date.' },
  { id: 'x3-III-4', sec: 'III', q: 'Which cost-basis method lets an investor minimize a taxable gain by selling specific high-basis lots?', opts: ['FIFO', 'Average cost', 'Specific identification', 'LIFO is required'], correct: 2, exp: 'Specific identification lets the investor choose which lots (e.g., highest cost) to sell, minimizing the gain.' },
  { id: 'x3-III-5', sec: 'III', q: 'Unused capital losses beyond the annual $3,000 ordinary-income offset are:', opts: ['Lost permanently', 'Carried forward to future years indefinitely', 'Refunded by the IRS', 'Converted to a credit'], correct: 1, exp: 'Excess capital losses carry forward indefinitely for individuals to offset future gains and up to $3,000 of ordinary income per year.' },
  { id: 'x3-III-6', sec: 'III', q: 'The standard settlement cycle for most U.S. stock trades is currently:', opts: ['T+3', 'T+2', 'T+1', 'Same day'], correct: 2, exp: 'Regular-way settlement moved to T+1 (one business day after trade date) in 2024.' },
  { id: 'x3-III-7', sec: 'III', q: 'The unlimited marital deduction allows:', opts: ['Tax-free gifts/bequests to a U.S.-citizen spouse', 'Unlimited gifts to anyone', 'Avoidance of income tax', 'Skipping RMDs'], correct: 0, exp: 'Transfers to a U.S.-citizen spouse are free of gift and estate tax under the unlimited marital deduction.' },
  { id: 'x3-III-8', sec: 'III', q: 'In 2026, a married couple electing gift splitting can give a single recipient up to how much annually, gift-tax-free?', opts: ['$19,000', '$30,000', '$38,000', '$15 million'], correct: 2, exp: 'Gift splitting combines both spouses\' $19,000 exclusions: 2 × $19,000 = $38,000 per recipient (2026).' },
  { id: 'x3-III-9', sec: 'III', q: 'A key advantage of an irrevocable trust over a revocable trust is that it:', opts: ['Can be changed anytime', 'Removes assets from the grantor\'s taxable estate', 'Avoids all income tax', 'Is simpler to create'], correct: 1, exp: 'Assets in an irrevocable trust are generally removed from the grantor\'s estate; revocable-trust assets remain in the estate.' },
  { id: 'x3-III-10', sec: 'III', q: 'A bypass (credit shelter) trust is primarily used to:', opts: ['Avoid probate only', 'Use both spouses\' estate tax exclusions to reduce estate taxes', 'Fund education', 'Eliminate income tax'], correct: 1, exp: 'A bypass trust preserves the first spouse\'s exclusion so both spouses\' exemptions shelter assets from estate tax.' },
  { id: 'x3-III-11', sec: 'III', q: 'A special needs trust is designed to:', opts: ['Disqualify a beneficiary from benefits', 'Provide for a disabled beneficiary without jeopardizing government benefits eligibility', 'Avoid all taxes', 'Replace a 529 plan'], correct: 1, exp: 'A special needs trust supplements care for a disabled beneficiary while preserving means-tested government benefits.' },
  { id: 'x3-III-12', sec: 'III', q: 'Which does NOT avoid probate?', opts: ['Assets titled JTWROS', 'A transfer-on-death (TOD) account', 'Assets in a living trust', 'Assets passing by a will'], correct: 3, exp: 'Property passing under a will goes through probate; JTWROS, TOD, and living-trust assets bypass it.' },
  { id: 'x3-III-13', sec: 'III', q: 'A "per stirpes" beneficiary designation means a deceased beneficiary\'s share passes to:', opts: ['The other named beneficiaries equally', 'That beneficiary\'s descendants', 'The estate', 'Charity'], correct: 1, exp: 'Per stirpes routes a deceased beneficiary\'s share down to their own descendants.' },
  { id: 'x3-III-14', sec: 'III', q: 'For an IRA, the named beneficiary designation generally:', opts: ['Is overridden by the will', 'Overrides instructions in the will', 'Has no legal effect', 'Requires probate'], correct: 1, exp: 'Beneficiary designations on IRAs and life insurance control distribution and override the will.' },
  { id: 'x3-III-15', sec: 'III', q: 'An employee can afford only limited retirement savings. The adviser should usually first recommend contributing to the 401(k):', opts: ['Nothing — use a taxable account', 'At least enough to capture the full employer match', 'The maximum regardless of budget', 'Only after age 50'], correct: 1, exp: 'Capturing the full employer match is an immediate, guaranteed return and is typically the first priority.' },
  { id: 'x3-III-16', sec: 'III', q: 'A young client who expects to be in a HIGHER tax bracket in retirement should generally favor a:', opts: ['Traditional (pre-tax) account', 'Roth (after-tax) account', 'Non-qualified annuity only', 'Taxable account only'], correct: 1, exp: 'Paying tax now (Roth) is advantageous when future rates are expected to be higher than today\'s.' },
  { id: 'x3-III-17', sec: 'III', q: 'Which is a valid exception to the 10% early-withdrawal penalty on an IRA before age 59½?', opts: ['Buying a vacation', 'A first-time home purchase (up to $10,000)', 'Any withdrawal', 'Paying credit cards'], correct: 1, exp: 'Exceptions include a first-time home purchase (up to $10,000), qualified education, disability, and substantially equal payments.' },
  { id: 'x3-III-18', sec: 'III', q: 'A 72(t) "substantially equal periodic payments" program allows an investor to:', opts: ['Skip RMDs', 'Take early IRA distributions without the 10% penalty', 'Double contributions', 'Avoid income tax entirely'], correct: 1, exp: 'A 72(t) SEPP schedule lets a pre-59½ investor avoid the 10% penalty (ordinary income tax still applies).' },
  { id: 'x3-III-19', sec: 'III', q: 'Under SECURE 2.0, the penalty for failing to take an RMD was reduced to:', opts: ['50%', '25% (10% if corrected promptly)', '0%', '100%'], correct: 1, exp: 'The excise tax on missed RMDs fell to 25%, and 10% if the shortfall is corrected within the correction window.' },
  { id: 'x3-III-20', sec: 'III', q: 'Under SECURE 2.0, unused 529 plan funds may be rolled to a Roth IRA, subject to a lifetime cap of:', opts: ['$10,000', '$35,000', 'No limit', '$7,000'], correct: 1, exp: 'Up to $35,000 lifetime may roll from a 529 to the beneficiary\'s Roth IRA if the account has been open 15+ years.' },
  { id: 'x3-III-21', sec: 'III', q: 'A nonworking spouse can fund a spousal IRA based on:', opts: ['No income at all', 'The working spouse\'s earned income on a joint return', 'Investment income only', 'Social Security only'], correct: 1, exp: 'A spousal IRA lets a nonworking spouse contribute using the working spouse\'s earned income (joint filing).' },
  { id: 'x3-III-22', sec: 'III', q: 'A key difference between an FSA and an HSA is that:', opts: ['HSA funds generally roll over year to year; FSAs are largely use-it-or-lose-it', 'FSAs roll over forever', 'HSAs require no health plan', 'FSAs are investment accounts'], correct: 0, exp: 'HSA balances roll over and grow; FSAs are mostly use-it-or-lose-it with limited carryover.' },
  { id: 'x3-III-23', sec: 'III', q: 'Under ERISA, employee salary-deferral contributions to a 401(k) are:', opts: ['Subject to a vesting schedule', 'Always 100% vested immediately', 'Forfeited if the employee leaves', 'Vested after 10 years'], correct: 1, exp: 'An employee\'s own deferrals are always 100% vested; employer contributions may follow a vesting schedule.' },
  { id: 'x3-III-24', sec: 'III', q: 'Relying too heavily on an initial piece of information when making decisions is the behavioral bias of:', opts: ['Anchoring', 'Diversification', 'Dollar-cost averaging', 'Rebalancing'], correct: 0, exp: 'Anchoring is over-weighting an initial reference point (such as a purchase price) when judging value.' },
  { id: 'x3-III-25', sec: 'III', q: 'An investor who holds losing stocks too long to avoid realizing a loss is exhibiting:', opts: ['Loss aversion', 'Overconfidence', 'Herding', 'Anchoring'], correct: 0, exp: 'Loss aversion is feeling losses more acutely than equivalent gains, leading to holding losers too long.' },
  { id: 'x3-III-26', sec: 'III', q: 'A bond ladder is constructed to:', opts: ['Concentrate all maturities in one year', 'Stagger maturities to manage reinvestment and interest-rate risk and provide liquidity', 'Maximize leverage', 'Avoid all bonds'], correct: 1, exp: 'A ladder spreads maturities over time, smoothing reinvestment risk and providing periodic liquidity.' },
  { id: 'x3-III-27', sec: 'III', q: 'Diversification reduces which type of risk?', opts: ['Systematic (market) risk', 'Unsystematic (company-specific) risk', 'Interest-rate risk on all bonds', 'Inflation risk entirely'], correct: 1, exp: 'Diversification reduces unsystematic (security-specific) risk; systematic market risk cannot be diversified away.' },
  { id: 'x3-III-28', sec: 'III', q: 'A stock bought at $100 is sold at $110 after paying a $5 dividend. The holding-period return is:', opts: ['10%', '15%', '5%', '11%'], correct: 1, exp: 'HPR = (price change + income) ÷ cost = (10 + 5) ÷ 100 = 15%.' },
  { id: 'x3-III-29', sec: 'III', q: 'Before recommending illiquid long-term investments, an adviser should generally ensure the client has:', opts: ['Maximum leverage', 'An adequate emergency fund / liquidity reserve', 'No insurance', 'Only growth stocks'], correct: 1, exp: 'Suitability calls for adequate liquidity/emergency reserves before committing to illiquid, long-horizon investments.' },
  { id: 'x3-III-30', sec: 'III', q: 'The difference between a marginal tax rate and an effective tax rate is that the marginal rate is:', opts: ['Total tax ÷ total income', 'The rate applied to the last dollar of income', 'Always lower than effective', 'Only for capital gains'], correct: 1, exp: 'The marginal rate applies to the next/last dollar earned; the effective rate is total tax divided by total income.' },

  // ---------------- SECTION IV — Laws & Ethics ----------------
  { id: 'x3-IV-1', sec: 'IV', q: 'An accountant who gives securities advice that is solely incidental to accounting practice and charges no special fee is:', opts: ['An investment adviser', 'Excluded from the IA definition', 'A federal covered adviser', 'A broker-dealer'], correct: 1, exp: 'Lawyers, accountants, teachers, and engineers (LATE) are excluded when advice is incidental and not separately compensated.' },
  { id: 'x3-IV-2', sec: 'IV', q: 'The distinction between an exclusion and an exemption is that an exclusion means a person:', opts: ['Is an IA but need not register', 'Is not an investment adviser at all', 'Must register federally', 'Is barred from the industry'], correct: 1, exp: 'An exclusion removes a person from the definition; an exemption means they are an IA but are relieved from registering.' },
  { id: 'x3-IV-3', sec: 'IV', q: 'A "wrap fee" program charges a single fee for advice and execution and requires the adviser to deliver:', opts: ['No disclosure', 'A wrap fee brochure (Form ADV Part 2A, Appendix 1)', 'Only a confirmation', 'A municipal official statement'], correct: 1, exp: 'Wrap fee sponsors must provide a specialized wrap fee program brochure (ADV 2A Appendix 1).' },
  { id: 'x3-IV-4', sec: 'IV', q: 'An adviser doing business in 15 or more states:', opts: ['Must register only in its home state', 'May register with the SEC as a federal covered adviser', 'Is exempt from all registration', 'Must register with FINRA'], correct: 1, exp: 'A multi-state adviser (required to register in 15+ states) may instead register federally with the SEC.' },
  { id: 'x3-IV-5', sec: 'IV', q: 'An adviser solely to private funds with less than $150 million in such assets is generally:', opts: ['Required to fully register with each state', 'An exempt reporting adviser', 'Prohibited from operating', 'A broker-dealer'], correct: 1, exp: 'The private fund adviser exemption (under $150M in private fund AUM) makes the firm an exempt reporting adviser.' },
  { id: 'x3-IV-6', sec: 'IV', q: 'An adviser that provides advice exclusively through an interactive website qualifies for:', opts: ['No registration', 'The SEC internet adviser exemption (federal registration)', 'State-only registration always', 'FINRA membership'], correct: 1, exp: 'The internet adviser exemption permits SEC registration for advisers operating solely through an interactive website.' },
  { id: 'x3-IV-7', sec: 'IV', q: 'Under the Uniform Securities Act, a complete registration application generally becomes effective at:', opts: ['Immediately on filing', 'Noon of the 30th day after filing, absent a stop order', 'One year later', 'The Administrator\'s sole discretion forever'], correct: 1, exp: 'Absent a denial/stop order, registration becomes effective at noon on the 30th day after a complete filing.' },
  { id: 'x3-IV-8', sec: 'IV', q: 'Registrations under the Uniform Securities Act expire:', opts: ['Every 5 years', 'December 31, requiring annual renewal', 'Never', 'On the registrant\'s birthday'], correct: 1, exp: 'BD, agent, IA, and IAR registrations expire December 31 each year and must be renewed.' },
  { id: 'x3-IV-9', sec: 'IV', q: 'An adviser that cannot meet the minimum net worth requirement may instead:', opts: ['Ignore the requirement', 'Post a surety bond', 'Register with FINRA', 'Stop taking clients permanently'], correct: 1, exp: 'The USA permits a surety bond in lieu of meeting the minimum net worth/financial requirement.' },
  { id: 'x3-IV-10', sec: 'IV', q: 'Form ADV-W is filed to:', opts: ['Register a new adviser', 'Withdraw an investment adviser\'s registration', 'Report a customer complaint', 'Apply for an exemption'], correct: 1, exp: 'Form ADV-W is used to withdraw an adviser\'s registration (full or partial).' },
  { id: 'x3-IV-11', sec: 'IV', q: 'Which is grounds for the Administrator to deny or revoke a registration?', opts: ['Earning commissions', 'A felony or securities-related misdemeanor conviction within the past 10 years', 'Having many clients', 'Charging performance fees to qualified clients'], correct: 1, exp: 'Convictions for felonies or securities-related misdemeanors within 10 years are statutory grounds for action.' },
  { id: 'x3-IV-12', sec: 'IV', q: 'The Securities Act of 1933 primarily regulates:', opts: ['Secondary-market trading', 'The issuance of new securities (primary market), including registration and prospectus delivery', 'Investment advisers', 'State Administrators'], correct: 1, exp: 'The 1933 Act governs new issues — registration, the prospectus, and full disclosure in the primary market.' },
  { id: 'x3-IV-13', sec: 'IV', q: 'During the cooling-off period of a registered public offering, an underwriter may:', opts: ['Sell the security', 'Accept indications of interest and distribute a preliminary prospectus (red herring)', 'Guarantee allocations', 'Set the final price publicly'], correct: 1, exp: 'During the ≥20-day cooling-off period no sales occur; firms gather indications of interest and circulate a red herring.' },
  { id: 'x3-IV-14', sec: 'IV', q: 'A tombstone advertisement is:', opts: ['A binding offer to sell', 'A limited announcement that is not an offer', 'A prospectus substitute', 'Illegal'], correct: 1, exp: 'A tombstone is a permitted, limited announcement of an offering; it is not itself an offer to sell.' },
  { id: 'x3-IV-15', sec: 'IV', q: 'The Securities Exchange Act of 1934:', opts: ['Created the SEC and regulates the secondary market and broker-dealers', 'Governs only new issues', 'Created NASAA', 'Regulates only mutual funds'], correct: 0, exp: 'The 1934 Act created the SEC and regulates secondary-market trading, exchanges, and broker-dealers.' },
  { id: 'x3-IV-16', sec: 'IV', q: 'The Investment Company Act of 1940 classifies investment companies into three types: management companies, unit investment trusts, and:', opts: ['Hedge funds', 'Face-amount certificate companies', 'Broker-dealers', 'REITs'], correct: 1, exp: 'The three statutory types are face-amount certificate companies, unit investment trusts, and management companies (open/closed-end).' },
  { id: 'x3-IV-17', sec: 'IV', q: 'Under the Howey test, an arrangement is an investment contract (security) if there is an investment of money in a common enterprise with an expectation of profit:', opts: ['From the investor\'s own efforts', 'Solely or primarily from the efforts of others', 'With no risk', 'Guaranteed by the government'], correct: 1, exp: 'The fourth Howey prong requires the expected profit to come primarily from the efforts of others.' },
  { id: 'x3-IV-18', sec: 'IV', q: 'Regulation D Rule 504 permits offerings up to:', opts: ['$1 million', '$5 million', '$10 million in a 12-month period', '$75 million'], correct: 2, exp: 'Rule 504 currently allows up to $10 million raised in any 12-month period.' },
  { id: 'x3-IV-19', sec: 'IV', q: 'Regulation A, Tier 2 allows an issuer to raise up to:', opts: ['$20 million', '$50 million', '$75 million in a 12-month period', 'Unlimited'], correct: 2, exp: 'Reg A Tier 2 permits up to $75 million in 12 months; Tier 1 permits up to $20 million.' },
  { id: 'x3-IV-20', sec: 'IV', q: 'An entity qualifies as an accredited investor if it has assets exceeding:', opts: ['$1 million', '$5 million (and was not formed to acquire the securities)', '$200,000', '$10 million'], correct: 1, exp: 'An entity with more than $5 million in assets (not formed to buy the offering) — or whose owners are all accredited — qualifies.' },
  { id: 'x3-IV-21', sec: 'IV', q: 'Securities issued by which of the following are EXEMPT from state registration?', opts: ['A venture-stage private company', 'A bank', 'A speculative oil & gas partnership', 'A crowdfunding portal'], correct: 1, exp: 'Bank-issued securities are exempt, along with government, municipal, insurance company, and nonprofit securities.' },
  { id: 'x3-IV-22', sec: 'IV', q: 'Which is an EXEMPT transaction?', opts: ['A solicited retail sale', 'An unsolicited customer order', 'A general advertising campaign', 'An IPO to the public'], correct: 1, exp: 'Unsolicited customer orders are exempt transactions, as are isolated non-issuer and institutional transactions.' },
  { id: 'x3-IV-23', sec: 'IV', q: 'Shares of a registered open-end mutual fund are an example of a:', opts: ['State-registered security', 'Federal covered security', 'Exempt transaction', 'Private placement'], correct: 1, exp: 'Investment company (mutual fund) shares are federal covered securities, subject to notice filing and antifraud at the state level.' },
  { id: 'x3-IV-24', sec: 'IV', q: 'For a federal covered adviser, a state generally may require:', opts: ['Full registration and its own books-and-records rules', 'Only a notice filing and fees (recordkeeping is preempted)', 'Nothing at all', 'FINRA membership'], correct: 1, exp: 'States may require notice filings/fees and retain antifraud authority but cannot impose their own recordkeeping on covered advisers.' },
  { id: 'x3-IV-25', sec: 'IV', q: 'An individual representing an issuer in an exempt transaction without receiving commissions is:', opts: ['Always an agent', 'Excluded from the agent definition', 'A broker-dealer', 'A federal covered adviser'], correct: 1, exp: 'Representing an issuer in certain exempt transactions (without commission) is excluded from the agent definition.' },
  { id: 'x3-IV-26', sec: 'IV', q: 'An agent may share in a customer\'s account only if:', opts: ['The agent decides to', 'There is written approval of the customer and firm, and sharing is proportional to the agent\'s contribution', 'The account is profitable', 'The customer is accredited'], correct: 1, exp: 'Sharing requires written consent of the customer and the firm and must be proportional to the agent\'s own investment.' },
  { id: 'x3-IV-27', sec: 'IV', q: 'Depositing client funds into the adviser\'s own business account is:', opts: ['Permitted with disclosure', 'Prohibited commingling of client and firm assets', 'Required for custody', 'A best practice'], correct: 1, exp: 'Commingling client funds with the firm\'s own funds is prohibited; client assets must be segregated.' },
  { id: 'x3-IV-28', sec: 'IV', q: 'When a violation has occurred, an adviser or broker-dealer may make a "right of rescission" offer; the client then has how long to accept?', opts: ['10 days', '30 days', '6 months', '2 years'], correct: 1, exp: 'A buyer who receives a valid rescission offer generally has 30 days to accept or reject it.' },
  { id: 'x3-IV-29', sec: 'IV', q: 'Regulation S-P requires firms to:', opts: ['Publish client account numbers', 'Provide privacy notices and safeguard nonpublic personal information', 'Share data freely', 'Eliminate recordkeeping'], correct: 1, exp: 'Reg S-P mandates privacy notices, opt-out rights for certain sharing, and safeguarding of customer information.' },
  { id: 'x3-IV-30', sec: 'IV', q: 'A Customer Identification Program (CIP) under AML rules requires firms to:', opts: ['Ignore identity', 'Verify the identity of customers when opening accounts', 'Guarantee returns', 'File a prospectus'], correct: 1, exp: 'Under the USA PATRIOT Act/BSA, firms must verify customer identity at account opening as part of CIP.' },
  { id: 'x3-IV-31', sec: 'IV', q: 'Regulation Best Interest (Reg BI) requires broker-dealers to:', opts: ['Meet only a suitability standard', 'Act in the retail customer\'s best interest at the time of a recommendation', 'Guarantee performance', 'Avoid all disclosures'], correct: 1, exp: 'Reg BI raised the BD standard to act in the retail customer\'s best interest (disclosure, care, conflict, compliance obligations).' },
  { id: 'x3-IV-32', sec: 'IV', q: 'Form CRS (relationship summary) must be delivered to retail investors by:', opts: ['Broker-dealers only', 'Investment advisers only', 'Both broker-dealers and SEC-registered advisers', 'Neither'], correct: 2, exp: 'Both broker-dealers and SEC-registered investment advisers must deliver Form CRS to retail investors.' },
  { id: 'x3-IV-33', sec: 'IV', q: 'In an agency cross transaction, an adviser acts as broker for both buyer and seller and must:', opts: ['Keep it secret', 'Obtain prior written consent and provide required disclosures', 'Recommend the trade to both sides', 'Guarantee a profit'], correct: 1, exp: 'Agency cross transactions require written client consent, disclosure of the conflict, and no recommendation to both sides.' },
  { id: 'x3-IV-34', sec: 'IV', q: 'Before completing a principal trade with an advisory client, an adviser (under IAA §206(3)) must:', opts: ['Do nothing', 'Disclose its principal capacity and obtain client consent for that transaction', 'Charge a performance fee', 'Notify FINRA only'], correct: 1, exp: 'Section 206(3) requires disclosure of the adviser\'s principal capacity and client consent before each such trade is completed.' },
  { id: 'x3-IV-35', sec: 'IV', q: 'An agent who wishes to engage in outside business activities must:', opts: ['Do so secretly', 'Provide prior written notice to the employing broker-dealer', 'Get NASAA approval', 'Quit the firm'], correct: 1, exp: 'Outside business activities require prior written notice to (and often approval by) the employing firm.' },
  { id: 'x3-IV-36', sec: 'IV', q: 'Spreading false rumors to inflate a stock and then selling is:', opts: ['Best execution', 'A pump-and-dump (market manipulation)', 'Tax-loss harvesting', 'Dollar-cost averaging'], correct: 1, exp: 'Pump-and-dump schemes manipulate prices through false information and are prohibited market manipulation.' },
  { id: 'x3-IV-37', sec: 'IV', q: 'An adviser is generally deemed to have custody when it:', opts: ['Gives advice for a fee', 'Serves as trustee or has authority to withdraw client funds (e.g., a general power of attorney)', 'Has more than 10 clients', 'Charges hourly'], correct: 1, exp: 'Acting as trustee or holding authority to withdraw client assets (such as a general POA) constitutes custody.' },
  { id: 'x3-IV-38', sec: 'IV', q: 'Recommending the same security to every client regardless of their individual profiles is:', opts: ['Efficient and proper', 'A "blanket recommendation" that violates suitability', 'Required by Reg BI', 'A best practice'], correct: 1, exp: 'Blanket recommendations ignore individual suitability and are an unethical/prohibited practice.' },
  { id: 'x3-IV-39', sec: 'IV', q: 'An IAR changing employers from one firm to another must ensure that:', opts: ['Only the IAR notifies the state', 'Both the IAR and the firms make the required notifications (U4/U5)', 'No notification is needed', 'FINRA approves first'], correct: 1, exp: 'On an IAR move, the terminating firm files U5, the new firm files U4, and the IAR is responsible for accuracy.' },
  { id: 'x3-IV-40', sec: 'IV', q: 'Telling a prospect that a security "can\'t lose" and is "guaranteed to rise" is:', opts: ['Allowed if sincere', 'A prohibited misrepresentation', 'Required disclosure', 'Acceptable for accredited investors'], correct: 1, exp: 'Misrepresenting risk or guaranteeing performance is a prohibited, fraudulent practice.' },
];

// ============================================================
// EXTRA4 — Advanced regulatory, behavioral, and compliance scenarios (highest-difficulty items)
// ============================================================
const EXTRA4_QUESTIONS = [
  // -------- SECTION III — Client Recommendations (Advanced Suitability & Behavioral) --------
  { id: 'x4-III-1', sec: 'III', q: 'A 45-year-old executive receives a $500K inheritance and asks an adviser to "grow my wealth aggressively" with a 10-year horizon. The client is already heavily concentrated in employer stock and has substantial income. The adviser MOST appropriately should:', opts: ['Immediately recommend an all-equity portfolio to maximize growth', 'Discuss the concentration risk, time horizon, other objectives, and create a diversified plan—not just follow the stated preference without context', 'Recommend bonds because the client is middle-aged', 'Suggest the client manage the money themselves'], correct: 1, exp: 'Suitable advice requires understanding the full situation (concentration, cash flow, risk tolerance, other goals). Blanket aggressiveness ignores suitability context—a common trap.' },

  { id: 'x4-III-2', sec: 'III', q: 'A client tells an adviser "I\'m afraid the market might crash—I want to be fully in cash." The adviser knows this client has a 25-year horizon and minimal other assets. Which response best balances honesty and suitability?', opts: ['Agree fully and move to 100% cash', 'Refuse to acknowledge the client\'s concern', 'Acknowledge the concern, explain the inflation/opportunity risk of 25 years in cash, and discuss a diversified plan aligned to their long-term goal', 'Push them into aggressive growth to overcome fear'], correct: 2, exp: 'Suitability requires acknowledging emotional concerns while educating and proposing advice aligned to facts (time horizon, goals). This tests behavioral understanding—a June 2023 focus.' },

  { id: 'x4-III-3', sec: 'III', q: 'An adviser receives a new client with $8M in taxable assets. The client is retired, needs $100K annually for living expenses, and owns a concentrated $2M position in a single stock with a $1.8M unrealized gain. The BEST first step is:', opts: ['Sell the concentrated position immediately to diversify', 'Recommend a covered call strategy', 'Develop a comprehensive plan including tax-loss harvesting, possible charitable strategies (donor-advised fund), staged diversification, and multi-account coordination', 'Recommend the client donate the stock to charity'], correct: 2, exp: 'High-net-worth planning requires integrated analysis: tax efficiency, charitable options, diversification timing. This is the hardest Section III topic; advisers must synthesize multiple variables.' },

  { id: 'x4-III-4', sec: 'III', q: 'A client exhibits overconfidence bias—they believe they can time the market better than professional managers. What is the adviser\'s BEST response?', opts: ['Support the view and allocate aggressively to active trading', 'Ignore the bias', 'Acknowledge their confidence, explain behavioral research on timing difficulty, show historical data, and propose a disciplined plan that accommodates a modest tactical allocation while maintaining core diversification', 'Refuse to work with them'], correct: 2, exp: 'Behavioral finance is critical (post-June 2023 emphasis). Advisers must recognize biases, educate without condescension, and set realistic expectations.' },

  { id: 'x4-III-5', sec: 'III', q: 'An adviser is hired by a business owner (age 62) to plan for retirement in 3 years. The firm value is ~$5M (undiversified). The client has not funded a qualified plan adequately. Which should the adviser address FIRST?', opts: ['Immediately invest all liquid assets in bonds', 'Ignore the business—it\'s not securities related', 'Discuss succession planning, business sale timing/structure, deferred compensation, qualified plan catch-up contributions, and diversification post-sale—since the business is the largest asset', 'Recommend buying life insurance only'], correct: 2, exp: 'Business owner retirement planning is complex; the adviser must coordinate succession, tax, and diversification. This tests integrated thinking.' },

  { id: 'x4-III-6', sec: 'III', q: 'A dually-registered professional (broker-dealer agent + IAR) recommends a Class A mutual fund to a retail client with a $50K investment. The fund has a 5% front-end load; the BD earns a commission; the adviser has a separate AUM agreement. The MOST problematic aspect is:', opts: ['The front-end load is always wrong', 'Recommending without considering whether an A-share load or B-share CDSC or institutional shares are more suitable given the client\'s situation and the dual compensation (commission + AUM)', 'The client is not accredited', 'The recommendation is permitted with no concern'], correct: 1, exp: 'Dual registration creates conflicts: commission on transaction + AUM incentive = bias toward frequent trading and higher costs. Advisers must prove the recommendation is best for the client, not the adviser.' },

  { id: 'x4-III-7', sec: 'III', q: 'A client is an ERISA plan fiduciary (corporate plan trustee) seeking advice on a $2M allocation. The adviser becomes the plan\'s investment adviser. Which statement BEST describes the adviser\'s obligations?', opts: ['The adviser has no fiduciary duty—the trustee bears all risk', 'The adviser becomes a fiduciary under ERISA and must act with the care, skill, diligence, and prudence of a professional in the field', 'The adviser can recommend speculative emerging markets without limits', 'Diversification is not required for ERISA accounts'], correct: 1, exp: 'An adviser to an ERISA plan becomes a fiduciary; ERISA 404(a) requires prudence, diversification, and due diligence. This is a sophisticated Section III topic.' },

  { id: 'x4-III-8', sec: 'III', q: 'An adviser with a $3M AUM client base receives a 1% AUM fee. The firm is also a BD and earns transaction commissions. A client asks about purchasing a direct-indexing strategy. The adviser is MOST ethically bound to:', opts: ['Avoid direct indexing because it reduces commissions', 'Recommend direct indexing WITHOUT considering that shifting to a lower-fee structure in this account may be in the client\'s best interest despite reducing AUM revenue', 'Compare direct indexing vs. mutual funds objectively, disclosing that lower AUM in direct indexing reduces the adviser\'s fee—and recommend what is truly suitable', 'Hide the fee structure from the client'], correct: 2, exp: 'Conflict disclosure and client best interest override the adviser\'s revenue. This tests ethical reasoning under ERISA and the Advisers Act fiduciary duty.' },

  { id: 'x4-III-9', sec: 'III', q: 'A 28-year-old with $50K in savings exhibits loss aversion—they react very negatively to any portfolio decline. Their 35-year horizon requires equity exposure for growth. The adviser should:', opts: ['Recommend 100% equities to force them to accept volatility', 'Recommend 100% bonds to avoid any loss', 'Educate on volatility, perhaps propose a moderate allocation with regular rebalancing, discuss the benefits of long-term investing, and monitor behavior', 'Refuse to advise due to psychological unsuitability'], correct: 2, exp: 'Behavioral coaching is a core adviser skill. Advisers must bridge the gap between optimal allocation and client ability to stay the course.' },

  { id: 'x4-III-10', sec: 'III', q: 'An adviser recommends a 60/40 portfolio to all clients regardless of age, income, or risk profile. This practice is:', opts: ['Efficient and proper', 'A "one-size-fits-all" violation of suitability—each recommendation must be tailored to that specific client\'s profile', 'Required by the SEC', 'A Reg BI best practice'], correct: 1, exp: 'Suitability ALWAYS requires individualized analysis. Blanket recommendations fail even if the portfolio itself is reasonable.' },

  // -------- SECTION IV — Laws & Ethics (Advanced regulatory and compliance scenarios) --------
  { id: 'x4-IV-1', sec: 'IV', q: 'An investment adviser\'s March 2025 marketing materials present past performance showing a 12% annualized return vs. the S&P 500\'s 9%. The adviser recommends that all such materials also disclose:', opts: ['Only the positive return', 'The basis for calculation, the time period, whether returns are net or gross, and any material conflicts/limitations', 'No disclosures needed if the data is accurate', 'Only the 12% figure'], correct: 1, exp: 'The SEC Marketing Rule (updated March 2025) requires detailed performance disclosures: calculation method, time horizon, net vs. gross, and limitations. This is post-2025 compliance.' },

  { id: 'x4-IV-2', sec: 'IV', q: 'An adviser with $90M in AUM is only regulated by state authorities. If the firm grows to $150M AUM:', opts: ['It remains state-only regulated forever', 'It must register with the SEC as a federal covered adviser', 'It is exempt from all registration', 'It must register with FINRA'], correct: 1, exp: 'The $110M threshold triggers federal (SEC) registration; state-only advisers at ≥$110M AUM must transition to SEC registration.' },

  { id: 'x4-IV-3', sec: 'IV', q: 'Form ADV Part 2A (the client brochure) must be delivered to EACH new client:', opts: ['Never—only upon request', 'At or before an advisory contract is signed', 'Only after one year of service', 'Only if the client is accredited'], correct: 1, exp: 'Form ADV Part 2A must be given at or before the client signs the advisory agreement; Part 2B (personnel) must be given at the same time.' },

  { id: 'x4-IV-4', sec: 'IV', q: 'An adviser discovers it has been charging performance fees to a client with net worth of $2.6M who manages only $1.2M with the adviser. The adviser should:', opts: ['Continue—the client is near the threshold', 'Acknowledge the client does not qualify as "qualified" under SEC rules ($2.7M net worth or ≥$1.4M under management) and cease performance fees or obtain a waiver', 'Immediately raise the fee by 5% to make up for the "mistake"', 'Hide the issue from the SEC'], correct: 1, exp: 'Qualified client thresholds (2026: $2.7M NW or $1.4M AUM) are strict. Violation requires remediation. This tests knowledge of current SEC definitions.' },

  { id: 'x4-IV-5', sec: 'IV', q: 'An IAR changes employment from Firm A to Firm B. Firm A is slow to file a Form U5 termination notice. Which is the IAR\'s BEST course?', opts: ['Wait indefinitely for Firm A', 'Immediately contact Firm A in writing demanding the U5 filing; if not filed within a reasonable time, escalate to the state Administrator', 'Ignore the delay and start new client relationships at Firm B', 'File the U5 themselves at Firm B'], correct: 1, exp: 'The employing firm is responsible for U5, but the IAR has a duty to ensure accurate, timely filings. Delays can result in administrative action.' },

  { id: 'x4-IV-6', sec: 'IV', q: 'An adviser with custody of client funds must arrange for a surprise examination. This audit is typically conducted by:', opts: ['The firm\'s own internal auditor', 'An independent CPA firm hired by the adviser and reviewed by the SEC/state', 'No one—surprise audits are optional', 'FINRA only'], correct: 1, exp: 'Surprise audit rules require an independent third party; the adviser cannot audit itself. The SEC/state reviews the results.' },

  { id: 'x4-IV-7', sec: 'IV', q: 'An adviser learns that a client is about to announce a major acquisition. The adviser has NOT been told the information is confidential, but knows it is "material nonpublic" and unreleased. The adviser should:', opts: ['Immediately recommend buying the stock to all clients', 'Trade immediately for the client\'s account', 'NOT trade on this information; it is insider information; pause any trading and consider requesting an instruction letter from the client', 'Sell the stock immediately'], correct: 2, exp: 'Material nonpublic information is insider information even without explicit secrecy language. Trading on it violates the securities laws. Advisers must have controls to prevent insider trading.' },

  { id: 'x4-IV-8', sec: 'IV', q: 'A broker-dealer agent offers a client a "proprietary" mutual fund managed by the BD\'s affiliate with a 2.5% expense ratio. A competing fund with an 0.15% ratio tracks the same index. The agent must:', opts: ['Recommend the proprietary fund—it\'s in the BD\'s interest', 'Ignore the fee difference', 'Disclose the conflict, compare the funds objectively, and recommend what is in the CLIENT\'s best interest (likely the low-cost index fund) under Reg BI', 'Lie about the fee difference'], correct: 2, exp: 'Reg BI (Regulation Best Interest) requires BDs to recommend based on client interest, not BD revenue. Conflicts must be disclosed and managed.' },

  { id: 'x4-IV-9', sec: 'IV', q: 'Section 16 of the Securities Exchange Act requires officers, directors, and 10% shareholders to file a Form 4 within:', opts: ['30 days of a transaction', '2 business days of a transaction', '60 days of a transaction', 'Once per year only'], correct: 1, exp: 'Form 4 reports of Section 16 insiders must be filed within 2 business days of the transaction; failure to file is a serious compliance issue.' },

  { id: 'x4-IV-10', sec: 'IV', q: 'Rule 10b5-1 plans allow insiders to buy/sell shares under a pre-arranged plan to avoid:', opts: ['All taxes', 'Accusations of trading on material nonpublic information', 'Registration', 'Margin calls'], correct: 1, exp: 'A Rule 10b5-1 plan (public company insiders) is a defense to insider trading allegations if set up in good faith when the insider has no material nonpublic info.' },

  { id: 'x4-IV-11', sec: 'IV', q: 'An adviser enters into an "agency cross transaction" (representing both buyer and seller). This requires:', opts: ['No disclosure—the adviser can act for both', 'Written consent of each client BEFOREHAND and a statement that it will NOT recommend the transaction to both sides', 'FINRA approval only', 'SEC approval but not written client consent'], correct: 1, exp: 'Agency cross transactions (IAA §206(3)) require PRIOR written consent from EACH client and disclosure that the adviser will not recommend to both sides.' },

  { id: 'x4-IV-12', sec: 'IV', q: 'An adviser acts as a principal (not as an agent/broker) in trading with a client account. Under IAA §206(3) and state law, the adviser must:', opts: ['Do nothing special', 'Disclose the principal capacity to the client AND receive written consent for THAT SPECIFIC TRANSACTION', 'Only disclose once in the Form ADV 2A', 'Avoid principal trades entirely'], correct: 1, exp: 'Principal trades with advisory clients require specific written consent for each trade and disclosure of the conflict. A blanket disclosure is insufficient.' },

  { id: 'x4-IV-13', sec: 'IV', q: 'A state Administrator\'s statute of limitations for bringing an action is typically:', opts: ['1 year from the act', '3 years from discovery or 5 years from the act (whichever is earlier)', 'Unlimited', '10 years from the act'], correct: 1, exp: 'Most state USAs follow a 3-year discovery / 5-year absolute statute for civil actions, encouraging timely enforcement.' },

  { id: 'x4-IV-14', sec: 'IV', q: 'An agent engages in "churning"—excessive trading of a customer\'s account to generate commissions without regard to suitability. The MOST appropriate remedy available to the customer is:', opts: ['Criminal prosecution of the agent', 'A civil suit for damages (including reasonable costs and fees)', 'Mandatory rescission of all trades', 'Nothing—churning is not prohibited'], correct: 1, exp: 'Churning (excessive trading) violates antifraud and suitability rules; customers may seek damages and costs in civil suits. Criminal action is rare but possible.' },

  { id: 'x4-IV-15', sec: 'IV', q: 'An adviser with $50M AUM is being acquired by a larger firm. The smaller adviser must:', opts: ['Do nothing—no disclosure needed', 'Disclose the acquisition to clients and offer them the right to withdraw without penalty within a reasonable period', 'Immediately close all client accounts', 'Only notify the SEC'], correct: 1, exp: 'Material changes (like an acquisition) trigger disclosure requirements. Clients must be informed and given a withdrawal window (e.g., 30 days) without penalty.' },

  { id: 'x4-IV-16', sec: 'IV', q: 'An adviser enters into a soft-dollar arrangement where a broker rebates software in exchange for directing trades to the broker. This is permissible ONLY if:', opts: ['The adviser benefits financially', 'The software benefits the adviser\'s clients (e.g., portfolio analysis tools) and the arrangement is disclosed', 'The client is not told', 'It provides a personal benefit to the adviser'], correct: 1, exp: 'Soft dollars (§28(e) safe harbor) are permitted only for brokerage/research that benefits clients, must be disclosed, and cannot be for personal advancer perks.' },

  { id: 'x4-IV-17', sec: 'IV', q: 'An adviser\'s contract with a client contains an exculpatory clause that purports to waive the client\'s right to sue for violations of the Advisers Act. This clause is:', opts: ['Valid and binding', 'Void—the Advisers Act prohibits waiver of compliance', 'Only valid for large accounts', 'Valid only in writing'], correct: 1, exp: 'The Advisers Act §47(b) voids any waiver of compliance; clients cannot contractually give up their legal rights.' },

  { id: 'x4-IV-18', sec: 'IV', q: 'During a transition when an adviser merges with another firm, the adviser must deliver a new Form ADV Part 2A to each existing client and receive acknowledgment:', opts: ['Never—no new delivery needed', 'Within 120 days of the material change', '5 years after the merger', 'Only if the fee structure changes'], correct: 1, exp: 'Material changes (mergers, significant fee increases) trigger new brochure delivery and client acknowledgment requirements within ~120 days.' },

  { id: 'x4-IV-19', sec: 'IV', q: 'An adviser recommends complex structured notes to a retired, unsophisticated client without assessing understanding or suitability. This is a violation of:', opts: ['Nothing—structured notes are always suitable', 'CAPM', 'The fiduciary standard (duty of care) and suitability—especially for vulnerable clients', 'Tax law only'], correct: 2, exp: 'Recommending complex products without assessing suitability and client understanding breaches the fiduciary duty of care and violates the Advisers Act.' },

  { id: 'x4-IV-20', sec: 'IV', q: 'A compliance officer discovers that an adviser has failed to deliver Form ADV Part 2B (personnel updates) to new clients for 2 months. The firm should:', opts: ['Ignore it if no client complained', 'Immediately remediate: deliver Part 2B retroactively, document the failure, notify affected clients, and implement controls to prevent recurrence', 'Wait for a regulatory exam to address it', 'Only notify if asked'], correct: 1, exp: 'Delivery failures must be remediated promptly: retroactive delivery, client notification, and corrective controls. This tests compliance responsibility.' },

  { id: 'x4-IV-21', sec: 'IV', q: 'An adviser is required to reasonably supervise its employees and representatives. If an IAR violates securities laws, the firm may be liable if it:', opts: ['The firm did nothing to supervise', 'The firm knew or reasonably should have known of the violation', 'The firm had no written policies', 'All of the above'], correct: 3, exp: 'Supervisory liability arises when the firm knows/should know of violations and fails to act. Written policies and active monitoring are essential.' },
];

export const QUESTIONS = [...BASE_QUESTIONS, ...EXTRA_QUESTIONS, ...EXTRA2_QUESTIONS, ...EXTRA3_QUESTIONS, ...EXTRA4_QUESTIONS];

export const SECTION_QUESTION_COUNTS = QUESTIONS.reduce((acc, q) => {
  acc[q.sec] = (acc[q.sec] || 0) + 1;
  return acc;
}, {});
